import { QuizQuestion } from '@/types';

export const quizQuestions: QuizQuestion[] = [

  // ─── MODULE 1 — Torah et Pentateuque ───────────────────────────────────────

  { id: 'q1-1', moduleId: 1, difficulty: 'facile', question: 'Quel est le premier mot de la Torah ?', options: ['Chema', 'Bereshit', 'Anokhi', 'Vayikra'], correctAnswer: 1, explanation: 'La Torah commence par « Bereshit » (בְּרֵאשִׁית), qui signifie « Au commencement ». Ce mot ouvre le livre de la Genèse.', source: 'Genèse 1:1' },

  { id: 'q1-2', moduleId: 1, difficulty: 'facile', question: 'Combien de livres compose la Torah ?', options: ['3', '4', '5', '7'], correctAnswer: 2, explanation: 'La Torah comprend cinq livres : Bereshit, Chémot, Vayikra, Bamidbar et Devarim. On l\'appelle aussi le Pentateuque ou Hamisha Houmchei Torah.', source: 'Tradition rabbinique, Talmud Bavli, Berakhot 5a' },

  { id: 'q1-3', moduleId: 1, difficulty: 'facile', question: 'Quel personnage reçoit la Torah au mont Sinaï ?', options: ['Abraham', 'David', 'Moïse', 'Aaron'], correctAnswer: 2, explanation: 'Moïse (Mochè) reçoit la Torah au mont Sinaï lors de la révélation divine. Cet événement est appelé Matan Torah, le « Don de la Torah ».', source: 'Exode 19-20' },

  { id: 'q1-4', moduleId: 1, difficulty: 'facile', question: 'Comment appelle-t-on l\'alliance entre Dieu et Abraham, scellée par la circoncision ?', options: ['Brit Milah', 'Brit Matan', 'Kiddouchine', 'Shevouah'], correctAnswer: 0, explanation: 'La Brit Milah (alliance de la circoncision) est le signe de l\'alliance entre Dieu et Abraham, transmis à tous ses descendants mâles. Elle est pratiquée le huitième jour après la naissance.', source: 'Genèse 17:10-14' },

  { id: 'q1-5', moduleId: 1, difficulty: 'facile', question: 'Quel est le nom hébreu de l\'Exode d\'Égypte ?', options: ['Akédat Yitshak', 'Matan Torah', 'Yetsiat Mitsrayim', 'Brit Avot'], correctAnswer: 2, explanation: 'Yetsiat Mitsrayim (יְצִיאַת מִצְרַיִם) signifie « la sortie d\'Égypte ». Cet événement fondateur est commémoré chaque année lors de la fête de Pessah.', source: 'Exode 12:51' },

  { id: 'q1-6', moduleId: 1, difficulty: 'facile', question: 'Combien de commandements (Mitzvot) recense la tradition rabbinique dans la Torah ?', options: ['10', '248', '365', '613'], correctAnswer: 3, explanation: 'La tradition dénombre 613 Mitzvot dans la Torah : 248 commandements positifs (à faire) et 365 interdictions (à ne pas faire). Ce décompte est attribué à Rabbi Simlai.', source: 'Talmud Bavli, Makkot 23b' },

  { id: 'q1-7', moduleId: 1, difficulty: 'facile', question: 'Quel fleuve Moïse écarte-t-il pour permettre aux Hébreux de fuir l\'armée de Pharaon ?', options: ['Le Jourdain', 'Le Nil', 'L\'Euphrate', 'La mer des Joncs (mer Rouge)'], correctAnswer: 3, explanation: 'C\'est la mer des Joncs (Yam Souf) que Dieu écarte par la main de Moïse, permettant aux Hébreux de traverser à pied sec. L\'armée égyptienne y périt ensuite.', source: 'Exode 14:21-29' },

  { id: 'q1-8', moduleId: 1, difficulty: 'moyen', question: 'Quel est le nom du dernier livre de la Torah, qui contient les discours d\'adieu de Moïse ?', options: ['Vayikra', 'Bamidbar', 'Devarim', 'Chémot'], correctAnswer: 2, explanation: 'Devarim (Deutéronome) est le cinquième et dernier livre de la Torah. Il rapporte les discours que Moïse prononce avant sa mort, récapitulant la Loi pour le peuple.', source: 'Deutéronome 1:1' },

  { id: 'q1-9', moduleId: 1, difficulty: 'moyen', question: 'Quelle est la première des dix plaies d\'Égypte ?', options: ['Les sauterelles', 'Les ténèbres', 'L\'eau transformée en sang', 'Les grenouilles'], correctAnswer: 2, explanation: 'La première plaie est la transformation des eaux du Nil en sang. Les dix plaies ont pour but de contraindre Pharaon à libérer le peuple hébreu.', source: 'Exode 7:14-25' },

  { id: 'q1-10', moduleId: 1, difficulty: 'moyen', question: 'Comment nomme-t-on l\'épisode où Abraham s\'apprête à sacrifier son fils Isaac ?', options: ['Brit Milah', 'Akédat Yitshak', 'Matan Torah', 'Aliyah laRegel'], correctAnswer: 1, explanation: 'L\'Akédat Yitshak (la Ligature d\'Isaac) est le récit où Dieu éprouve la foi d\'Abraham en lui demandant de sacrifier son fils Isaac. Un ange arrête le geste au dernier moment.', source: 'Genèse 22:1-19' },

  { id: 'q1-11', moduleId: 1, difficulty: 'moyen', question: 'Quel est le nom hébreu du livre de l\'Exode ?', options: ['Vayikra', 'Bereshit', 'Chémot', 'Bamidbar'], correctAnswer: 2, explanation: 'Chémot (שְׁמוֹת) signifie « noms » en hébreu ; c\'est le deuxième livre de la Torah, qui raconte l\'esclavage en Égypte, la naissance de Moïse et la sortie d\'Égypte.', source: 'Exode 1:1' },

  { id: 'q1-12', moduleId: 1, difficulty: 'moyen', question: 'Quel est le terme hébreu désignant le pacte ou alliance entre Dieu et le peuple juif ?', options: ['Mitsvah', 'Brit', 'Kavod', 'Teshuvah'], correctAnswer: 1, explanation: 'Le mot Brit (בְּרִית) désigne l\'alliance. La Torah mentionne plusieurs alliances (Brit), notamment avec Noé, Abraham et le peuple d\'Israël au Sinaï.', source: 'Genèse 15:18 ; Exode 19:5' },

  { id: 'q1-13', moduleId: 1, difficulty: 'moyen', question: 'Quel livre de la Torah contient principalement les lois rituelles et sacrificielles des cohanim (prêtres) ?', options: ['Bereshit', 'Bamidbar', 'Devarim', 'Vayikra'], correctAnswer: 3, explanation: 'Vayikra (Lévitique) est consacré aux lois de pureté, aux sacrifices et aux fonctions sacerdotales. Son nom hébreu vient du verbe « appeler » — Dieu appelle Moïse.', source: 'Lévitique 1:1' },

  { id: 'q1-14', moduleId: 1, difficulty: 'moyen', question: 'Quelle phrase résume le principe central de la Torah selon Rabbi Akiva ?', options: ['Chema Israël, l\'Éternel est notre Dieu', 'Tu aimeras ton prochain comme toi-même', 'Souviens-toi du jour du Chabbat', 'Je suis l\'Éternel ton Dieu'], correctAnswer: 1, explanation: 'Rabbi Akiva déclare que « Tu aimeras ton prochain comme toi-même » (Lévitique 19:18) est le grand principe fondateur de la Torah. Ben Azzaï propose quant à lui le verset de Genèse 5:1.', source: 'Talmud Yerouchalmi, Nedarim 9:4 ; Lévitique 19:18' },

  { id: 'q1-15', moduleId: 1, difficulty: 'moyen', question: 'Combien de tribus composent le peuple d\'Israël selon la Torah ?', options: ['10', '11', '12', '13'], correctAnswer: 2, explanation: 'Le peuple d\'Israël se compose de douze tribus, issues des douze fils de Jacob (Yaakov). Chaque tribu porte le nom d\'un fils ou, pour Joseph, de ses deux fils Éphraïm et Manassé.', source: 'Genèse 49 ; Nombres 1' },

  { id: 'q1-16', moduleId: 1, difficulty: 'difficile', question: 'Quel est le terme désignant les 248 commandements positifs de la Torah selon le décompte de Maïmonide ?', options: ['Lavin', 'Asséh', 'Karet', 'Chévouot'], correctAnswer: 1, explanation: 'Les commandements positifs (« tu feras ») sont appelés Mitsvot Asséh (מִצְוֹת עֲשֵׂה). Ils sont au nombre de 248, correspondant symboliquement aux 248 membres du corps humain selon la tradition.', source: 'Maïmonide, Séfer HaMitsvot, introduction' },

  { id: 'q1-17', moduleId: 1, difficulty: 'difficile', question: 'Quel concept désigne la lecture annuelle cyclique complète de la Torah en synagogue ?', options: ['Haftarah', 'Parashat HaChavouah', 'Keriat HaTorah', 'Alyah'], correctAnswer: 1, explanation: 'La Parashat HaChavouah (« la section de la semaine ») désigne la portion de Torah lue chaque semaine. Le cycle annuel se termine et recommence à Sim\'hat Torah.', source: 'Talmud Bavli, Meguilah 29b' },

  { id: 'q1-18', moduleId: 1, difficulty: 'difficile', question: 'Quel est le nom hébreu du buisson ardent depuis lequel Dieu se révèle à Moïse ?', options: ['Har Sinaï', 'Snéh', 'Orev', 'Chorev'], correctAnswer: 1, explanation: 'Le Snéh (סְנֶה) est le buisson ardent. Dieu y révèle Son nom à Moïse (Ehyé Acher Ehyé) et lui confie la mission de libérer le peuple hébreu d\'Égypte.', source: 'Exode 3:2-4' },

  { id: 'q1-19', moduleId: 1, difficulty: 'difficile', question: 'Selon la tradition, quelle est la signification du nom divin « Ehyé Acher Ehyé » révélé à Moïse ?', options: ['Je suis celui qui punit', 'Je serai ce que je serai / Je suis ce que je suis', 'Dieu de tes pères', 'Le Tout-Puissant'], correctAnswer: 1, explanation: '« Ehyé Acher Ehyé » (אֶהְיֶה אֲשֶׁר אֶהְיֶה) signifie littéralement « Je serai ce que je serai » ou « Je suis ce que je suis ». Il exprime l\'essence éternelle et indéfinissable de Dieu.', source: 'Exode 3:14 ; Maïmonide, Guide des égarés I, 63' },

  { id: 'q1-20', moduleId: 1, difficulty: 'difficile', question: 'Quelle loi de la Torah interdit de cuire un chevreau dans le lait de sa mère, fondant l\'interdiction de mélanger viande et lait ?', options: ['Lévitique 11:3', 'Exode 23:19', 'Nombres 15:38', 'Deutéronome 6:4'], correctAnswer: 1, explanation: 'L\'interdiction « Tu ne feras pas cuire un chevreau dans le lait de sa mère » (Exode 23:19) apparaît trois fois dans la Torah. Les rabbins en ont déduit l\'ensemble de la cacherout concernant la séparation viande-lait.', source: 'Exode 23:19 ; Talmud Bavli, Houlin 115b' },

  // ─── MODULE 2 — Les Fêtes Juives ──────────────────────────────────────────

  { id: 'q2-1', moduleId: 2, difficulty: 'facile', question: 'Quel est le jour de repos hebdomadaire dans le judaïsme ?', options: ['Le dimanche', 'Le vendredi', 'Le Chabbat (samedi)', 'Le lundi'], correctAnswer: 2, explanation: 'Le Chabbat (שַׁבָּת) est le septième jour de la semaine, jour de repos et de sanctification. Il débute au coucher du soleil le vendredi et se termine à la nuit tombante le samedi.', source: 'Exode 20:8-11 ; Genèse 2:2-3' },

  { id: 'q2-2', moduleId: 2, difficulty: 'facile', question: 'Quel rituel marque le début du Chabbat dans les foyers juifs ?', options: ['Le Kiddouch', 'L\'allumage des bougies', 'La Havdalah', 'La prière Minha'], correctAnswer: 1, explanation: 'L\'allumage des bougies par la femme du foyer marque l\'entrée du Chabbat. Il est généralement effectué dix-huit minutes avant le coucher du soleil, accompagné d\'une bénédiction.', source: 'Talmud Bavli, Chabbat 25b ; Choulhan Aroukh, Orah Hayim 263' },

  { id: 'q2-3', moduleId: 2, difficulty: 'facile', question: 'Quel rituel clôture le Chabbat et marque la séparation entre le sacré et le profane ?', options: ['Le Kiddouch', 'La Havdalah', 'L\'Arvit', 'Le Moussaf'], correctAnswer: 1, explanation: 'La Havdalah (הַבְדָּלָה, « séparation ») est la cérémonie de clôture du Chabbat. Elle comprend des bénédictions sur le vin, les aromates et une bougie tressée, symbolisant la distinction entre saint et profane.', source: 'Talmud Bavli, Berakhot 33a ; Choulhan Aroukh, Orah Hayim 296' },

  { id: 'q2-4', moduleId: 2, difficulty: 'facile', question: 'Quel est le mets traditionnel mangé lors du Séder de Pessah pour rappeler la hâte des Hébreux en quittant l\'Égypte ?', options: ['La Matzah (pain azyme)', 'Le Maror', 'Le Harosset', 'L\'agneau pascal'], correctAnswer: 0, explanation: 'La Matzah (מַצָּה), pain sans levain, commémore le fait que les Hébreux n\'eurent pas le temps de laisser lever leur pain avant de fuir l\'Égypte. Elle est le symbole central de Pessah.', source: 'Exode 12:39 ; Talmud Bavli, Pessahim 116a' },

  { id: 'q2-5', moduleId: 2, difficulty: 'facile', question: 'Quel instrument est soufflé lors de Roch Hachana ?', options: ['La trompette (hatsotserah)', 'Le shofar', 'La harpe (kinor)', 'Le tambourin (tof)'], correctAnswer: 1, explanation: 'Le shofar (שׁוֹפָר), corne de bélier, est soufflé pendant Roch Hachana. Son son appelle à l\'introspection et au repentir. La Torah ordonne de faire entendre « la voix du shofar ».', source: 'Lévitique 23:24 ; Nombres 29:1 ; Talmud Bavli, Roch Hachana 16a' },

  { id: 'q2-6', moduleId: 2, difficulty: 'facile', question: 'Quelle nourriture symbolique mange-t-on lors du repas de Roch Hachana pour augurer une « douce » nouvelle année ?', options: ['Du pain challah rond', 'De la pomme trempée dans le miel', 'Du poisson entier', 'Des dattes'], correctAnswer: 1, explanation: 'La pomme trempée dans le miel est l\'un des symboles les plus connus de Roch Hachana. On prononce le vœu : « Qu\'il nous soit accordé une bonne et douce année. »', source: 'Talmud Bavli, Horayot 12a ; Choulhan Aroukh, Orah Hayim 583' },

  { id: 'q2-7', moduleId: 2, difficulty: 'facile', question: 'Quelle fête commémore la sortie d\'Égypte et est célébrée au printemps ?', options: ['Souccot', 'Shavouot', 'Pessah', 'Roch Hachana'], correctAnswer: 2, explanation: 'Pessah (פֶּסַח) commémore la sortie d\'Égypte (Yetsiat Mitsrayim). Elle dure sept jours en Israël (huit en diaspora) et comprend le Séder, le repas rituel du premier soir.', source: 'Exode 12:1-28 ; Lévitique 23:5-8' },

  { id: 'q2-8', moduleId: 2, difficulty: 'moyen', question: 'Comment s\'appelle le texte liturgique lu lors du Séder de Pessah ?', options: ['Le Machzor', 'La Haggadah', 'Le Siddour', 'La Meguila'], correctAnswer: 1, explanation: 'La Haggadah (הַגָּדָה, « récit ») est le texte rituel du Séder. Elle retrace la sortie d\'Égypte, inclut des hymnes et des questions des enfants, notamment les « quatre questions » (Mah Nishtanah).', source: 'Talmud Bavli, Pessahim 116a ; Haggadah de Pessah' },

  { id: 'q2-9', moduleId: 2, difficulty: 'moyen', question: 'Quel est le nom de la prière d\'inauguration du Chabbat récitée sur le vin ?', options: ['Birkat HaMazon', 'Kiddouch', 'Havdalah', 'Motsi'], correctAnswer: 1, explanation: 'Le Kiddouch (קִידּוּשׁ, « sanctification ») est la bénédiction récitée sur un verre de vin pour sanctifier le Chabbat ou les fêtes. Il existe un Kiddouch du soir (Grand Kiddouch) et un Kiddouch du matin.', source: 'Talmud Bavli, Pessahim 106a ; Choulhan Aroukh, Orah Hayim 271' },

  { id: 'q2-10', moduleId: 2, difficulty: 'moyen', question: 'Quel est le jeûne le plus solennel du calendrier juif ?', options: ['Le jeûne de Gedaliah', 'Tisha BeAv', 'Yom Kippour', 'Le jeûne d\'Esther'], correctAnswer: 2, explanation: 'Yom Kippour (יוֹם כִּיפּוּר, « Jour du Grand Pardon ») est le jour le plus saint du calendrier juif. Le jeûne dure 25 heures et est accompagné de cinq offices liturgiques ainsi que de la prière Kol Nidré.', source: 'Lévitique 16:29-34 ; 23:27-32' },

  { id: 'q2-11', moduleId: 2, difficulty: 'moyen', question: 'Quel est le nom de la hutte construite lors de la fête de Souccot ?', options: ['La Soucca', 'Le Tachbets', 'Le Mishkan', 'L\'Aravah'], correctAnswer: 0, explanation: 'La Soucca (סֻכָּה) est une cabane temporaire à toit de végétaux, dans laquelle on mange et parfois on dort pendant les sept jours de Souccot. Elle rappelle les tentes des Hébreux dans le désert.', source: 'Lévitique 23:42-43 ; Talmud Bavli, Soucca 2a' },

  { id: 'q2-12', moduleId: 2, difficulty: 'moyen', question: 'Quelle fête célèbre le don de la Torah au mont Sinaï ?', options: ['Souccot', 'Shavouot', 'Pessah', 'Pourim'], correctAnswer: 1, explanation: 'Shavouot (שָׁבוּעוֹת, « Semaines ») est célébrée cinquante jours après Pessah. Elle commémore le don de la Torah au Sinaï et correspond aussi à la fête des prémices agricoles.', source: 'Exode 19-20 ; Lévitique 23:15-21' },

  { id: 'q2-13', moduleId: 2, difficulty: 'moyen', question: 'Quelle est la prière centrale de Yom Kippour, annulant les vœux de l\'année écoulée ?', options: ['Avinou Malkenou', 'Kol Nidré', 'Neilah', 'Vidouï'], correctAnswer: 1, explanation: 'Kol Nidré (כָּל נִדְרֵי, « Tous les vœux ») est une déclaration araméenne récitée à l\'entrée de Yom Kippour. Elle annule symboliquement les vœux involontaires contractés envers Dieu.', source: 'Choulhan Aroukh, Orah Hayim 619 ; Talmud Bavli, Nedarim 23b' },

  { id: 'q2-14', moduleId: 2, difficulty: 'moyen', question: 'Quelle fête clôture le cycle annuel de lecture de la Torah et le rouvre aussitôt ?', options: ['Shemini Atseret', 'Sim\'hat Torah', 'Hoshana Rabbah', 'Shavouot'], correctAnswer: 1, explanation: 'Sim\'hat Torah (שִׂמְחַת תּוֹרָה, « Joie de la Torah ») marque la fin et le recommencement immédiat de la lecture annuelle de la Torah. On danse avec les rouleaux (Hakafot) dans la synagogue.', source: 'Talmud Bavli, Meguilah 31a ; Choulhan Aroukh, Orah Hayim 669' },

  { id: 'q2-15', moduleId: 2, difficulty: 'moyen', question: 'Quel est le nom des quatre espèces végétales rassemblées lors de Souccot ?', options: ['Arba Minim', 'Arba Koussot', 'Arba Parashiot', 'Arba Imahot'], correctAnswer: 0, explanation: 'Les Arba Minim (אַרְבָּעָה מִינִים, « quatre espèces ») sont le loulav (palme), l\'etrog (cédrat), des branches de myrte (hadas) et des branches de saule (aravah). On les secoue lors des offices.', source: 'Lévitique 23:40 ; Talmud Bavli, Soucca 37b' },

  { id: 'q2-16', moduleId: 2, difficulty: 'difficile', question: 'Quel est le terme désignant le pain tressé béni lors du Chabbat ?', options: ['Matzah', 'Challah', 'Lechem Michné', 'Bikoure'], correctAnswer: 2, explanation: 'Le Lechem Michné (לֶחֶם מִשְׁנֶה, « pain double ») désigne les deux pains tressés (challot) posés sur la table du Chabbat. Ils rappellent la double portion de manne reçue au désert avant le Chabbat.', source: 'Exode 16:22 ; Choulhan Aroukh, Orah Hayim 274' },

  { id: 'q2-17', moduleId: 2, difficulty: 'difficile', question: 'Quel est le nom du dernier office de Yom Kippour, réputé être le moment le plus solennel de la journée ?', options: ['Shaharit', 'Moussaf', 'Minha', 'Neilah'], correctAnswer: 3, explanation: 'Neilah (נְעִילָה, « fermeture ») est la prière de clôture de Yom Kippour, symbolisant la fermeture des portes du ciel. Le shofar est soufflé à la fin de Neilah, marquant la fin du jeûne.', source: 'Talmud Bavli, Yoma 87b ; Choulhan Aroukh, Orah Hayim 623' },

  { id: 'q2-18', moduleId: 2, difficulty: 'difficile', question: 'Combien de coupes de vin doit-on boire lors du Séder de Pessah, et à quoi correspondent-elles ?', options: ['Deux coupes, rappelant le pain et le vin', 'Trois coupes, pour les patriarches', 'Quatre coupes, aux quatre expressions de délivrance', 'Cinq coupes, pour les cinq livres de la Torah'], correctAnswer: 2, explanation: 'On boit quatre coupes de vin lors du Séder de Pessah. Elles correspondent aux quatre expressions de délivrance mentionnées dans l\'Exode : « je vous sortirai, je vous délivrerai, je vous rachèterai, je vous prendrai. »', source: 'Exode 6:6-7 ; Talmud Bavli, Pessahim 99b' },

  { id: 'q2-19', moduleId: 2, difficulty: 'difficile', question: 'Quelle est la signification du terme « Tashlich » pratiqué lors de Roch Hachana ?', options: ['Sonnerie du shofar au lever du soleil', 'Jet symbolique des péchés dans l\'eau courante', 'Récitation du Hallel', 'Bénédiction des enfants par les parents'], correctAnswer: 1, explanation: 'Tachlich (תַּשְׁלִיך, « tu jetteras ») est une pratique médiévale consistant à se rendre près d\'un cours d\'eau et à y jeter symboliquement ses péchés (souvent représentés par des miettes de pain).', source: 'Michée 7:19 ; Choulhan Aroukh, Orah Hayim 583:2' },

  { id: 'q2-20', moduleId: 2, difficulty: 'difficile', question: 'Quel est le nom du rite consistant à vérifier et éliminer tout levain avant Pessah ?', options: ['Biur Hamets', 'Bedikat Hamets', 'Bitul Hamets', 'Mechirat Hamets'], correctAnswer: 1, explanation: 'Bedikat Hamets (בְּדִיקַת חָמֵץ, « vérification du levain ») est la fouille rituelle du levain effectuée à la bougie la nuit précédant Pessah. Elle est suivie du Biur Hamets (brûlage du levain) le matin.', source: 'Talmud Bavli, Pessahim 2a ; Choulhan Aroukh, Orah Hayim 432' },

  // ─── MODULE 3 — Talmud et Tradition Orale ─────────────────────────────────

  { id: 'q3-1', moduleId: 3, difficulty: 'facile', question: 'Comment s\'appelle le premier grand recueil de la Loi orale, codifié vers 200 de l\'ère commune ?', options: ['Le Talmud', 'La Michna', 'La Guemara', 'Le Midrach'], correctAnswer: 1, explanation: 'La Michna (מִשְׁנָה) est la première codification de la Torah orale, rédigée par Rabbi Yéhouda HaNassi vers 200 de l\'ère commune. Elle se divise en six ordres (Sédarim) et soixante-trois traités.', source: 'Talmud Bavli, Baba Metsia 85b' },

  { id: 'q3-2', moduleId: 3, difficulty: 'facile', question: 'Quel sage est l\'auteur principal de la rédaction de la Michna ?', options: ['Raban Gamliel', 'Rabbi Akiva', 'Rabbi Yéhouda HaNassi', 'Rav Achi'], correctAnswer: 2, explanation: 'Rabbi Yéhouda HaNassi (« le Prince »), surnommé simplement « Rabbi », compile et rédige la Michna vers l\'an 200 de l\'ère commune. Il est l\'une des figures les plus importantes du judaïsme rabbinique.', source: 'Talmud Bavli, Baba Metsia 85a' },

  { id: 'q3-3', moduleId: 3, difficulty: 'facile', question: 'Quel est le nom donné à la discussion et aux commentaires de la Michna qui forment le Talmud ?', options: ['Aggada', 'Midrach', 'Guemara', 'Piyout'], correctAnswer: 2, explanation: 'La Guemara (גְּמָרָא, « étude/achèvement ») est l\'ensemble des discussions et analyses rabbiniques de la Michna. La Michna et la Guemara réunies forment le Talmud.', source: 'Talmud Bavli, introduction générale' },

  { id: 'q3-4', moduleId: 3, difficulty: 'facile', question: 'Combien y a-t-il d\'ordres (Sédarim) dans la Michna ?', options: ['4', '5', '6', '7'], correctAnswer: 2, explanation: 'La Michna se divise en six ordres (Chacha Sédarim, שִׁשָּׁה סְדָרִים). Chaque ordre regroupe des traités thématiques couvrant les domaines de l\'agriculture, des fêtes, du droit civil, du culte du Temple, et plus encore.', source: 'Michna, introduction ; Talmud Bavli, Chabbat 31a' },

  { id: 'q3-5', moduleId: 3, difficulty: 'facile', question: 'Quel est le grand commentateur du XIe siècle dont les explications du Talmud sont indispensables encore aujourd\'hui ?', options: ['Maïmonide', 'Nahmanide', 'Rachi', 'Joseph Karo'], correctAnswer: 2, explanation: 'Rachi (Rabbi Chlomo Yitshaki, 1040-1105) est l\'auteur du commentaire le plus lu et le plus utilisé sur le Talmud et la Torah. Né à Troyes (France), son commentaire accompagne la quasi-totalité des éditions du Talmud.', source: 'Talmud Bavli (éditions standard) ; biographies de Rachi, XIe s.' },

  { id: 'q3-6', moduleId: 3, difficulty: 'facile', question: 'Comment appelle-t-on la partie narrative et homilétique du Talmud, par opposition à la loi ?', options: ['Halakha', 'Aggada', 'Midrach halakhique', 'Peskita'], correctAnswer: 1, explanation: 'L\'Aggada (אַגָּדָה) désigne l\'ensemble des récits, paraboles, méditations éthiques et discussions théologiques du Talmud, par opposition à la Halakha qui est le droit juif. Les deux constituent les deux piliers de la littérature talmudique.', source: 'Talmud Bavli, Sotah 40a ; introduction classique du Talmud' },

  { id: 'q3-7', moduleId: 3, difficulty: 'moyen', question: 'Quels sont les deux Talmuds existants ?', options: ['Talmud de Babylone et Talmud de Jérusalem', 'Talmud de Rome et Talmud d\'Alexandrie', 'Talmud de Michna et Talmud de Guemara', 'Talmud de Rachi et Talmud de Maïmonide'], correctAnswer: 0, explanation: 'Il existe deux Talmuds : le Talmud de Jérusalem (Yerouchalmi), rédigé en Palestine vers le IVe siècle, et le Talmud de Babylone (Bavli), rédigé en Babylonie vers le Ve-VIe siècle. Ce dernier fait autorité dans la pratique juive.', source: 'Talmud Bavli, Sanhedrin 24a' },

  { id: 'q3-8', moduleId: 3, difficulty: 'moyen', question: 'Quel terme désigne la loi juive pratique telle qu\'elle est codifiée et appliquée ?', options: ['Aggada', 'Machloket', 'Halakha', 'Psakim'], correctAnswer: 2, explanation: 'La Halakha (הֲלָכָה, « la marche ») est l\'ensemble du droit juif normatif, couvrant tous les aspects de la vie : prière, fêtes, alimentaire, droit civil, éthique. Elle est issue de la Torah, du Talmud et des décisions rabbiniques.', source: 'Talmud Bavli, Berakhot 11a ; Maïmonide, Michné Torah, introduction' },

  { id: 'q3-9', moduleId: 3, difficulty: 'moyen', question: 'Quel est le nom du grand code de loi juive rédigé par Joseph Karo au XVIe siècle ?', options: ['Michné Torah', 'Choulhan Aroukh', 'Arba Tourim', 'Séfer HaMitsvot'], correctAnswer: 1, explanation: 'Le Choulhan Aroukh (שֻׁלְחָן עָרוּךְ, « Table dressée ») est rédigé par Rabbi Joseph Karo (1488-1575) et publié en 1565. C\'est le code de loi juive standard, enrichi des gloses de Rabbi Moïse Isserles (Rema) pour les Ashkénazes.', source: 'Joseph Karo, Choulhan Aroukh (1565) ; introduction de l\'auteur' },

  { id: 'q3-10', moduleId: 3, difficulty: 'moyen', question: 'Comment appelle-t-on les disciples de Rachi qui continuèrent et approfondirent ses commentaires au XIIe-XIIIe siècle ?', options: ['Guéonim', 'Rishonim', 'Tosafot', 'Aharonim'], correctAnswer: 2, explanation: 'Les Tosafistes (בַּעֲלֵי הַתּוֹסָפוֹת, « auteurs des additions ») sont les élèves et continuateurs de Rachi, principalement en France et en Allemagne aux XIIe-XIIIe siècles. Leurs commentaires (Tosafot) figurent en marge du Talmud.', source: 'Talmud Bavli (éditions standard), marges des pages' },

  { id: 'q3-11', moduleId: 3, difficulty: 'moyen', question: 'Quel est le nom du grand code juridique de Maïmonide, synthèse de toute la Halakha ?', options: ['Séfer HaMitsvot', 'Guide des égarés', 'Michné Torah', 'Choulhan Aroukh'], correctAnswer: 2, explanation: 'Le Michné Torah (מִשְׁנֵה תּוֹרָה, « Répétition de la Torah ») est la grande codification de Maïmonide (Rabbi Moïse ben Maïmon, 1135-1204). Rédigé en hébreu clair, il couvre l\'intégralité de la Halakha en quatorze volumes.', source: 'Maïmonide, Michné Torah, introduction' },

  { id: 'q3-12', moduleId: 3, difficulty: 'moyen', question: 'Que désigne le terme « Guéonim » dans l\'histoire de la transmission de la Torah ?', options: ['Les sages du Talmud', 'Les chefs des académies babyloniennes du VIIe au XIe siècle', 'Les commentateurs de Rachi', 'Les dirigeants spirituels hassidiques'], correctAnswer: 1, explanation: 'Les Guéonim (גְּאוֹנִים, « les excellents ») sont les chefs des grandes académies babyloniennes de Soura et Poumbedita entre le VIIe et le XIe siècle. Ils jouèrent un rôle central dans la diffusion de la Halakha en diaspora.', source: 'Tradition historique ; Iggéret Rav Sherira Gaon (986)' },

  { id: 'q3-13', moduleId: 3, difficulty: 'moyen', question: 'Quel est le nom du traité de la Michna consacré aux maximes éthiques des sages ?', options: ['Avoda Zara', 'Avot (Pirkei Avot)', 'Sanhedrin', 'Ketubot'], correctAnswer: 1, explanation: 'Pirkei Avot (פִּרְקֵי אָבוֹת, « Chapitres des Pères ») est le traité éthique de la Michna le plus lu. Il rassemble des maximes morales et spirituelles des grands sages de la tradition rabbinique.', source: 'Michna, Avot 1:1' },

  { id: 'q3-14', moduleId: 3, difficulty: 'moyen', question: 'Quel est le terme désignant un débat ou désaccord entre autorités rabbiniques ?', options: ['Haskama', 'Machloket', 'Psak', 'Takana'], correctAnswer: 1, explanation: 'La Machloket (מַחְלֹקֶת, « désaccord ») désigne un débat halakhique entre sages. Le Talmud affirme que les débats « pour le nom du Ciel » (comme ceux de Hillel et Chammaï) sont légitimes et enrichissants.', source: 'Michna Avot 5:17 ; Talmud Bavli, Erouvine 13b' },

  { id: 'q3-15', moduleId: 3, difficulty: 'moyen', question: 'Qui est l\'auteur des « Arba Tourim » (Quatre Rangées), précurseur du Choulhan Aroukh ?', options: ['Rachi', 'Rabbi Yéhouda HaNassi', 'Jacob ben Asher (le Baal HaTourim)', 'Nahmanide'], correctAnswer: 2, explanation: 'Les Arba Tourim (אַרְבָּעָה טוּרִים) sont rédigés par Rabbi Jacob ben Asher (le Baal HaTourim, v. 1269-1340). Ce code en quatre parties structure la Halakha selon les mêmes divisions que le futur Choulhan Aroukh.', source: 'Jacob ben Asher, Arba Tourim (XIVe s.)' },

  { id: 'q3-16', moduleId: 3, difficulty: 'difficile', question: 'Quel est le nom du processus par lequel un décisionnaire rabbinique rend une décision halakhique ?', options: ['Hora\'ah', 'Drasha', 'Haskama', 'Hekhsher'], correctAnswer: 0, explanation: 'La Hora\'ah (הוֹרָאָה, « enseignement/décision ») désigne l\'acte de rendre une décision rabbinique (Psak Halakha). Seul un sage suffisamment érudit et reconnu peut exercer la Hora\'ah dans un domaine donné.', source: 'Talmud Bavli, Sanhedrin 5b' },

  { id: 'q3-17', moduleId: 3, difficulty: 'difficile', question: 'Quel terme désigne les sages cités dans la Michna (Ier-IIIe siècle) par opposition aux sages de la Guemara ?', options: ['Amoraïm', 'Tannaïm', 'Savora\'im', 'Guéonim'], correctAnswer: 1, explanation: 'Les Tannaïm (תַּנָּאִים, du verbe « enseigner ») sont les sages de la période de la Michna, du Ier au IIIe siècle de l\'ère commune. Les Amoraïm leur succèdent et discutent la Michna dans la Guemara.', source: 'Talmud Bavli, introduction ; Epistle de Rav Sherira Gaon' },

  { id: 'q3-18', moduleId: 3, difficulty: 'difficile', question: 'Quel est le principe talmudique affirmant que la loi suit toujours l\'école de Hillel (Beit Hillel) plutôt que celle de Chammaï (Beit Chammaï) ?', options: ['Kol hamachmir tavo alav berakha', 'Halakha keBeit Hillel', 'Dibra Torah kilchon benei adam', 'Lo titgodedu'], correctAnswer: 1, explanation: '« Halakha keBeit Hillel » (הֲלָכָה כְּבֵית הִלֵּל) signifie que la décision légale suit l\'école de Hillel. Le Talmud rapporte qu\'une voix céleste (Bat Kol) a tranché en faveur de Beit Hillel car ses membres étaient humbles et citaient aussi l\'opinion adverse.', source: 'Talmud Bavli, Erouvine 13b' },

  { id: 'q3-19', moduleId: 3, difficulty: 'difficile', question: 'Que signifie le concept de « Torah min HaChamaïm » ?', options: ['La Torah interprétée par les sages', 'La Torah est d\'origine céleste/divine', 'L\'étude de la Torah est une obligation quotidienne', 'La Torah protège celui qui l\'étudie'], correctAnswer: 1, explanation: '« Torah min HaChamaïm » (תּוֹרָה מִן הַשָּׁמַיִם, « Torah venant du Ciel ») est un principe fondamental du judaïsme affirm que la Torah a été révélée par Dieu à Moïse. C\'est l\'un des treize principes de foi de Maïmonide.', source: 'Maïmonide, Commentaire de la Michna, Sanhédrin 10:1 (13 principes)' },

  { id: 'q3-20', moduleId: 3, difficulty: 'difficile', question: 'Qu\'appelle-t-on le « Chlochah Oussrim » (trente-deux) dans l\'herméneutique talmudique ?', options: ['Les trente-deux noms divins de la Kabbale', 'Les treize règles de Rabbi Ichmaël plus dix-neuf règles supplémentaires', 'Les règles d\'interprétation de la Torah selon Rabbi Eliezer ben Yose HaGalili', 'Les trente-deux traités de la Michna'], correctAnswer: 2, explanation: 'Rabbi Eliezer ben Yose HaGalili formule trente-deux règles (Lamed-Bet Middot) d\'interprétation pour les textes aggadiques de la Torah, complétant les treize règles herméneutiques d\'Ichmaël.', source: 'Baraïta de Rabbi Eliezer ben Yose HaGalili (Midrach, introduction)' },

  // ─── MODULE 4 — Kabbale et Mysticisme ─────────────────────────────────────

  { id: 'q4-1', moduleId: 4, difficulty: 'facile', question: 'Quel est le livre fondateur de la Kabbale, rédigé au XIIIe siècle en Espagne ?', options: ['Le Séfer Yetsira', 'Le Zohar', 'Le Séfer HaBahir', 'Les Tanya'], correctAnswer: 1, explanation: 'Le Zohar (זֹהַר, « Splendeur ») est le texte central de la Kabbale. Publié en Espagne au XIIIe siècle par Rabbi Moïse de León, il est traditionnellement attribué au Tanna Rabbi Chimon bar Yohaï du IIe siècle.', source: 'Zohar I, 1a ; Gershom Scholem, Les grandes tendances de la mystique juive' },

  { id: 'q4-2', moduleId: 4, difficulty: 'facile', question: 'Combien de Sefirot (attributs divins) la Kabbale dénombre-t-elle ?', options: ['7', '10', '12', '13'], correctAnswer: 1, explanation: 'La Kabbale distingue dix Sefirot (סְפִירוֹת) : Keter, Hokhma, Bina, Hesed, Guevourah, Tiferet, Netsah, Hod, Yessod et Malkhout. Elles représentent les attributs et canaux d\'émanation de la lumière divine.', source: 'Séfer Yetsira 1:4 ; Zohar I, 15a' },

  { id: 'q4-3', moduleId: 4, difficulty: 'facile', question: 'Comment appelle-t-on la source divine infinie et inconditionnée dans la Kabbale ?', options: ['Ein Sof', 'Keter', 'Malkhout', 'Tiferet'], correctAnswer: 0, explanation: 'Ein Sof (אֵין סוֹף, « sans fin ») désigne Dieu en tant qu\'infini absolu, au-delà de toute description et attribut. Les Sefirot sont les émanations par lesquelles l\'Ein Sof se manifeste dans le monde.', source: 'Zohar I, 11b ; Maïmonide, Guide des égarés I, 52 (antécédent philosophique)' },

  { id: 'q4-4', moduleId: 4, difficulty: 'facile', question: 'Quel est le nom du fondateur du mouvement hassidique au XVIIIe siècle ?', options: ['Rabbi Loew (Maharal)', 'Rabbi Nachman de Breslev', 'Baal Shem Tov (Rabbi Israël ben Eliezer)', 'Rabbi Schneur Zalman de Liadi'], correctAnswer: 2, explanation: 'Le Baal Shem Tov (בַּעַל שֵׁם טוֹב, « Maître du Bon Nom »), Rabbi Israël ben Eliezer (v. 1700-1760), est le fondateur du mouvement hassidique. Il prône la joie, la dévotion sincère et l\'accès de tous à la spiritualité.', source: 'Shivhei HaBesht (Éloge du Baal Shem Tov, 1815)' },

  { id: 'q4-5', moduleId: 4, difficulty: 'facile', question: 'Quel kabbaliste du XVIe siècle, surnommé l\'Ari, développe la Kabbale louria anique à Safed ?', options: ['Rabbi Joseph Karo', 'Rabbi Moïse Cordovero', 'Rabbi Isaac Louria (l\'Ari)', 'Rabbi Hayim Vital'], correctAnswer: 2, explanation: 'Rabbi Isaac Louria (1534-1572), surnommé l\'Ari (הָאֲרִי, « le lion »), développe une Kabbale nouvelle à Safed. Ses enseignements sur le Tsimtsoum, le Chévira et le Tikkoun sont transmis par son disciple Rabbi Hayim Vital.', source: 'Hayim Vital, Ets Hayim (arbre de vie) ; biographies de l\'Ari' },

  { id: 'q4-6', moduleId: 4, difficulty: 'moyen', question: 'Quel est le concept kabbalistique désignant le « retrait » ou « contraction » de Dieu pour permettre l\'existence du monde ?', options: ['Tikkoun', 'Tsimtsoum', 'Chévira', 'Or Ein Sof'], correctAnswer: 1, explanation: 'Le Tsimtsoum (צִמְצוּם, « contraction ») est un concept central de la Kabbale lourianiq ue. Dieu se « contracte » pour créer un espace vide (Halal) dans lequel le monde peut exister. C\'est le premier acte de la création selon l\'Ari.', source: 'Hayim Vital, Ets Hayim, Chaar HaHakdamot ; Zohar (allusion)' },

  { id: 'q4-7', moduleId: 4, difficulty: 'moyen', question: 'Que désigne le concept de « Tikkoun Olam » dans la Kabbale lourianiq ue ?', options: ['La prière du soir', 'La réparation ou rectification du monde', 'L\'étude intensive de la Torah', 'La purification avant le Chabbat'], correctAnswer: 1, explanation: 'Le Tikkoun Olam (תִּיקּוּן עוֹלָם, « réparation du monde ») désigne la mission de rectification spirituelle confiée à l\'humanité après la Chévira (brisure des vases). Chaque acte saint contribue à restaurer l\'harmonie divine.', source: 'Hayim Vital, Ets Hayim, Chaar HaChvirah ; Zohar II, 245b' },

  { id: 'q4-8', moduleId: 4, difficulty: 'moyen', question: 'Quel est le nom de la Séfira centrale de l\'arbre des Sefirot, associée à la beauté et à l\'harmonie ?', options: ['Keter', 'Hesed', 'Tiferet', 'Yessod'], correctAnswer: 2, explanation: 'Tiferet (תִּפְאֶרֶת, « beauté/splendeur ») est la sixième Séfira, au centre de l\'arbre des Sefirot. Elle représente l\'équilibre entre Hesed (amour) et Guevourah (rigueur) et est associée au Tétragramme divin.', source: 'Zohar I, 15a ; Séfer Yetsira 6:1' },

  { id: 'q4-9', moduleId: 4, difficulty: 'moyen', question: 'Quel est le livre hassidique fondamental écrit par Rabbi Schneur Zalman de Liadi, fondateur du Habad ?', options: ['Chivhei HaBesht', 'Noam Elimelekh', 'Tanya (Liqutei Amarim)', 'Méor Eynaïm'], correctAnswer: 2, explanation: 'Le Tanya (תַּנְיָא, « il a été enseigné »), ou Liqutei Amarim, est rédigé par Rabbi Schneur Zalman de Liadi (1745-1812), fondateur du hassidisme Habad. C\'est la synthèse philosophique du hassidisme intellectuel.', source: 'Schneur Zalman de Liadi, Tanya, 1797' },

  { id: 'q4-10', moduleId: 4, difficulty: 'moyen', question: 'Quel est le nom hébreu de la mystique de l\'ère pré-kabbalistique décrivant l\'ascension vers les palais célestes ?', options: ['Kabbale maasit', 'Littérature de Maaseh Merkava / Hekhalot', 'Aggadat Bereshit', 'Séfer HaChamaïm'], correctAnswer: 1, explanation: 'La littérature des Hekhalot (הֵיכָלוֹת, « palais ») et de Maaseh Merkavah (מַעֲשֵׂה מֶרְכָּבָה, « Œuvre du Char ») est la mystique juive ancienne (IIIe-VIIe siècles), décrivant l\'ascension de l\'âme à travers les palais célestes vers le trône divin.', source: 'Talmud Bavli, Haguiga 14b ; textes des Hekhalot' },

  { id: 'q4-11', moduleId: 4, difficulty: 'moyen', question: 'Selon la Kabbale, que désigne la « Chévira HaKelim » (brisure des vases) ?', options: ['La destruction du Premier Temple', 'La brisure des tables de la Loi par Moïse', 'L\'effondrement cosmique des vases divins lors de la création', 'La fin du monde selon le Zohar'], correctAnswer: 2, explanation: 'La Chévira HaKelim (שְׁבִירַת הַכֵּלִים, « brisure des vases ») est un concept lourianique. Lors de la création, les vases censés contenir la lumière divine s\'effondrent, dispersant des « étincelles » (Nitsotsot) dans le monde matériel. Le Tikkoun vise à les rassembler.', source: 'Hayim Vital, Ets Hayim, Chaar HaChvirah' },

  { id: 'q4-12', moduleId: 4, difficulty: 'moyen', question: 'Comment s\'appelle le premier texte connu de la mystique juive, bref traité sur les lettres hébraïques et les dix Sefirot ?', options: ['Zohar', 'Séfer HaBahir', 'Séfer Yetsira', 'Pirke de-Rabbi Eliezer'], correctAnswer: 2, explanation: 'Le Séfer Yetsira (סֵפֶר יְצִירָה, « Livre de la Création ») est le plus ancien texte de la mystique juive (peut-être IIIe-VIe siècle). Il traite des dix Sefirot et des vingt-deux lettres hébraïques comme instruments de la création.', source: 'Séfer Yetsira 1:1 ; Gershom Scholem, Jewish Gnosticism...' },

  { id: 'q4-13', moduleId: 4, difficulty: 'moyen', question: 'Quelle est la signification kabbalistique de la lettre Aleph (א), première lettre de l\'alphabet hébreu ?', options: ['Elle représente le bœuf et la force brute', 'Elle symbolise l\'unité divine et le commencement de toutes choses', 'Elle correspond uniquement au son vocalique', 'Elle représente la mort et la renaissance'], correctAnswer: 1, explanation: 'Dans la Kabbale, l\'Aleph (א) symbolise l\'unité divine (valeur numérique 1) et le principe de toutes choses. Sa forme unit le ciel et la terre, reflétant la médiation divine entre les mondes.', source: 'Zohar III, 2a ; Séfer Yetsira 2:1' },

  { id: 'q4-14', moduleId: 4, difficulty: 'difficile', question: 'Quel est le nom de la Séfira associée à la « couronne » et à la volonté divine la plus élevée ?', options: ['Hokhma', 'Bina', 'Keter', 'Tiferet'], correctAnswer: 2, explanation: 'Keter (כֶּתֶר, « couronne ») est la Séfira la plus élevée, quasi-identifiée à l\'Ein Sof. Elle représente la volonté divine originelle (Ratson), au-delà de toute intellection, source de toutes les autres Sefirot.', source: 'Zohar I, 15a ; Pardes Rimonim de Rabbi Moïse Cordovero' },

  { id: 'q4-15', moduleId: 4, difficulty: 'difficile', question: 'Selon la Kabbale lourianiq ue, qu\'est-ce que le « Reshimou » ?', options: ['L\'empreinte de lumière divine résiduelle après le Tsimtsoum', 'Le nom secret de Dieu selon le Zohar', 'La prière méditative centrale du hassidisme', 'Le récipient vide des Sefirot'], correctAnswer: 0, explanation: 'Le Reshimou (רְשִׁימוּ, « trace/empreinte ») est l\'empreinte de lumière divine restant dans le Halal (espace vide) après le Tsimtsoum. Il est essentiel pour permettre la réintroduction de la lumière (Kav) et la formation des Sefirot.', source: 'Hayim Vital, Ets Hayim, Chaar HaHakdamot, ch. 1' },

  { id: 'q4-16', moduleId: 4, difficulty: 'difficile', question: 'Quel est le concept hassidique désignant l\'annihilation du moi dans la prière intense ?', options: ['Deveikout', 'Bitul', 'Hisbonenut', 'Hitlahavout'], correctAnswer: 1, explanation: 'Le Bitul (בִּיטּוּל, « annulation ») désigne l\'effacement de l\'ego dans la contemplation divine. Dans le hassidisme Habad, le Bitul Hayech est l\'annulation de l\'être propre pour s\'unir à l\'Ein Sof.', source: 'Tanya, ch. 33 ; enseignements du Baal Shem Tov' },

  { id: 'q4-17', moduleId: 4, difficulty: 'difficile', question: 'Que désigne le concept de « Partsufim » dans la Kabbale lourianiq ue ?', options: ['Les niveaux de l\'âme humaine', 'Les configurations ou « visages » divins issus de la recomposition des Sefirot', 'Les dix plaies d\'Égypte relues symboliquement', 'Les noms des anges gardiens selon le Zohar'], correctAnswer: 1, explanation: 'Les Partsufim (פַּרְצוּפִים, « configurations/visages ») sont des regroupements dynamiques de Sefirot formant des « personnalités » divines, notamment Arikh Anpin (Grande Face), Abba (Père), Ima (Mère), Ze\'ir Anpin (Petite Face) et Nukva.', source: 'Hayim Vital, Ets Hayim, Chaar HaPartsufim' },

  { id: 'q4-18', moduleId: 4, difficulty: 'difficile', question: 'Quel est le terme hébreu désignant l\'adhésion ou l\'union mystique avec Dieu, objectif central de la vie spirituelle hassidique ?', options: ['Tsedakah', 'Deveikout', 'Avodat Hashem', 'Heshbon Nefesh'], correctAnswer: 1, explanation: 'La Deveikout (דְּבֵקוּת, « adhésion/attachement ») désigne l\'union mystique de l\'âme avec Dieu. Dans le hassidisme, elle est l\'aspiration suprême : maintenir en tout moment un lien conscient et vibrant avec le divin.', source: 'Deutéronome 10:20 ; Baal Shem Tov, Keter Chem Tov' },

  { id: 'q4-19', moduleId: 4, difficulty: 'difficile', question: 'Quel est le nom du kabbaliste espagnol du XIIIe siècle qui compose la majeure partie du Zohar selon la recherche académique ?', options: ['Nahmanide (Rabbi Moïse ben Nahman)', 'Abraham Aboulafia', 'Rabbi Moïse de León', 'Rabbi Ezra de Gérone'], correctAnswer: 2, explanation: 'La recherche académique, notamment les travaux de Gershom Scholem, attribue la rédaction du Zohar à Rabbi Moïse de León (v. 1240-1305), kabbaliste castillan. Il aurait pseudépigraphiquement attribué l\'œuvre à Rabbi Chimon bar Yohaï.', source: 'Gershom Scholem, Major Trends in Jewish Mysticism (1941), ch. 5' },

  { id: 'q4-20', moduleId: 4, difficulty: 'difficile', question: 'Quelle est la doctrine kabbalistique des quatre mondes (Olamot), du plus élevé au plus bas ?', options: ['Atsilout, Beriah, Yetsirah, Assiyah', 'Assiyah, Yetsirah, Beriah, Atsilout', 'Beriah, Atsilout, Assiyah, Yetsirah', 'Keter, Hokhma, Bina, Malkhout'], correctAnswer: 0, explanation: 'Les quatre mondes sont, du plus proche de l\'Ein Sof au plus éloigné : Atsilout (émanation), Beriah (création), Yetsirah (formation) et Assiyah (action/monde matériel). Chaque monde abrite des configurations propres de Sefirot.', source: 'Hayim Vital, Ets Hayim ; Zohar I, 40a (allusion) ; Pardes Rimonim' },

  // ─── MODULE 5 — Histoire du Peuple Juif ───────────────────────────────────

  { id: 'q5-1', moduleId: 5, difficulty: 'facile', question: 'En quelle année est proclamée la création de l\'État d\'Israël ?', options: ['1947', '1948', '1949', '1950'], correctAnswer: 1, explanation: 'L\'État d\'Israël est proclamé le 14 mai 1948 par David Ben Gourion, à Tel-Aviv. Ce jour correspond au 5 Iyar 5708 dans le calendrier hébreu et est célébré chaque année comme Yom HaAtsmaout.', source: 'Déclaration d\'indépendance d\'Israël, 14 mai 1948' },

  { id: 'q5-2', moduleId: 5, difficulty: 'facile', question: 'Quel terme hébreu désigne la dispersion du peuple juif hors de sa terre ?', options: ['Aliyah', 'Diaspora / Galout', 'Hitnatkout', 'Geoulah'], correctAnswer: 1, explanation: 'La Galout (גָּלוּת, « exil ») ou Diaspora désigne la dispersion du peuple juif hors d\'Israël. Cette situation commencée lors des exils assyrien et babylonien s\'est prolongée jusqu\'à nos jours pour une grande partie du peuple juif.', source: 'Lévitique 26:33 ; Deutéronome 28:64' },

  { id: 'q5-3', moduleId: 5, difficulty: 'facile', question: 'Quel roi biblique fait construire le Premier Temple à Jérusalem ?', options: ['David', 'Salomon', 'Ézéchias', 'Josias'], correctAnswer: 1, explanation: 'Le roi Salomon (Chelomo HaMelekh) construit le Premier Temple (Beit HaMikdach) à Jérusalem, vers 957 avant l\'ère commune, sur le mont Moriah. Ce Temple abrite l\'Arche d\'Alliance.', source: 'I Rois 6:1-38 ; II Chroniques 3-4' },

  { id: 'q5-4', moduleId: 5, difficulty: 'facile', question: 'En quelle année le Second Temple de Jérusalem est-il détruit par les Romains ?', options: ['63 avant l\'ère commune', '70 de l\'ère commune', '135 de l\'ère commune', '586 avant l\'ère commune'], correctAnswer: 1, explanation: 'Le Second Temple est détruit en 70 de l\'ère commune par les armées romaines de Titus, lors du siège de Jérusalem. Cet événement est commémoré chaque année le 9 Av (Tisha BeAv), jour de deuil et de jeûne.', source: 'Josèphe Flavius, Guerre des Juifs, VI ; Talmud Bavli, Yoma 9b' },

  { id: 'q5-5', moduleId: 5, difficulty: 'facile', question: 'Quel empire déporte le peuple juif lors de la destruction du Premier Temple en 586 avant l\'ère commune ?', options: ['L\'Empire assyrien', 'L\'Empire babylonien', 'L\'Empire perse', 'L\'Empire romain'], correctAnswer: 1, explanation: 'Nabuchodonosor II, roi de Babylone, détruit le Premier Temple en 586 avant l\'ère commune et déporte une grande partie du peuple juif à Babylone. Cet exil babylonien dure environ soixante-dix ans.', source: 'II Rois 24-25 ; Jérémie 52' },

  { id: 'q5-6', moduleId: 5, difficulty: 'facile', question: 'En quelle année les Juifs sont-ils expulsés d\'Espagne ?', options: ['1391', '1478', '1492', '1517'], correctAnswer: 2, explanation: 'L\'Edit d\'Alhambra, signé par les Rois Catholiques Ferdinand et Isabelle, expulse les Juifs d\'Espagne en 1492. Cette expulsion met fin à plusieurs siècles d\'une civilisation judéo-hispanique florissante (l\'âge d\'or séfarade).', source: 'Edit d\'Alhambra, 31 mars 1492 ; sources historiques séfarades' },

  { id: 'q5-7', moduleId: 5, difficulty: 'facile', question: 'Comment appelle-t-on le génocide des Juifs perpétré par l\'Allemagne nazie pendant la Seconde Guerre mondiale ?', options: ['La Pogrom', 'La Shoah', 'L\'Inquisition', 'La Nakba'], correctAnswer: 1, explanation: 'La Shoah (שׁוֹאָה, « catastrophe ») désigne le génocide de six millions de Juifs par le régime nazi entre 1941 et 1945. Yom HaChoah est commémorée le 27 Nisan.', source: 'Loi israélienne sur le Mémorial de la Shoah (1953) ; Yad Vashem' },

  { id: 'q5-8', moduleId: 5, difficulty: 'moyen', question: 'Quel roi perse autorise les Juifs à retourner en Israël et à reconstruire le Temple après l\'exil babylonien ?', options: ['Darius Ier', 'Cyrus II le Grand', 'Artaxerxès Ier', 'Xercès Ier'], correctAnswer: 1, explanation: 'Cyrus II le Grand, roi des Perses, promulgue en 538 avant l\'ère commune l\'Édit de Cyrus, autorisant les Juifs exilés à retourner en Judée et à rebâtir le Temple. Cet édit est cité dans le livre d\'Ezra.', source: 'Ezra 1:1-4 ; II Chroniques 36:22-23 ; Cylindre de Cyrus' },

  { id: 'q5-9', moduleId: 5, difficulty: 'moyen', question: 'Quel est le nom de la forteresse juive dont la chute en 73 de l\'ère commune symbolise la fin de la résistance juive contre Rome ?', options: ['Massada', 'Gamala', 'Jérusalem', 'Qumrân'], correctAnswer: 0, explanation: 'Massada (מְצָדָה) est la forteresse hérodienne sur le rocher du désert de Judée où neuf cent soixante Sicaires résistent aux Romains jusqu\'en 73 de l\'ère commune. Selon Josèphe, les défenseurs préfèrent mourir plutôt que de se rendre.', source: 'Josèphe Flavius, Guerre des Juifs, VII, 8-9' },

  { id: 'q5-10', moduleId: 5, difficulty: 'moyen', question: 'Quel texte fondateur du sionisme Theodore Herzl publie-t-il en 1896 ?', options: ['Der Judenstaat (L\'État juif)', 'Altneuland (Terre ancienne-nouvelle)', 'Auto-émancipation', 'Le sionisme pratique'], correctAnswer: 0, explanation: '« Der Judenstaat » (L\'État juif) est publié par Theodor Herzl en 1896. Ce pamphlet pose les bases politiques du mouvement sioniste et plaide pour la création d\'un État juif comme solution à l\'antisémitisme.', source: 'Theodor Herzl, Der Judenstaat, 1896' },

  { id: 'q5-11', moduleId: 5, difficulty: 'moyen', question: 'Quel est le nom de la résistance juive qui se soulève contre les Syriens grecs au IIe siècle avant l\'ère commune, célébrée lors de Hanoukka ?', options: ['La révolte de Bar Kokhba', 'La révolte des Maccabées (Hasmonéens)', 'La guerre des Zélotes', 'La révolte de Cyrénaïque'], correctAnswer: 1, explanation: 'La révolte des Maccabées (168-164 AEC), menée par Mattatias et son fils Juda Maccabée contre l\'hellénisation forcée d\'Antiochos IV Épiphane, aboutit à la reprise et purification du Temple. Cet événement est célébré à Hanoukka.', source: 'I Maccabées ; Talmud Bavli, Chabbat 21b' },

  { id: 'q5-12', moduleId: 5, difficulty: 'moyen', question: 'Quel mouvement de retour en terre d\'Israël commence à s\'organiser à la fin du XIXe siècle, antérieur au sionisme herzlien ?', options: ['L\'Hovevei Tsion (Amants de Sion)', 'L\'Alliance israélite universelle', 'Le Bund', 'Le Agudas Israël'], correctAnswer: 0, explanation: 'L\'Hovevei Tsion (חוֹבְבֵי צִיּוֹן, « Amants de Sion »), fondé dans les années 1880 en Europe de l\'Est, est le mouvement proto-sioniste qui organise les premières vagues d\'immigration (Aliyot) en Palestine avant Herzl.', source: 'Sources historiques ; Walter Laqueur, A History of Zionism' },

  { id: 'q5-13', moduleId: 5, difficulty: 'moyen', question: 'Quel est le nom de la conférence nazie de 1942 qui planifie la « Solution finale » ?', options: ['Conférence de Nuremberg', 'Conférence de Wannsee', 'Conférence de Potsdam', 'Conférence d\'Évian'], correctAnswer: 1, explanation: 'La Conférence de Wannsee se tient le 20 janvier 1942 en banlieue de Berlin. Les responsables nazis y coordonnent la « Solution finale de la question juive » (Endlösung), planifiant l\'extermination systématique des Juifs d\'Europe.', source: 'Procès-verbal de la Conférence de Wannsee, 20 janvier 1942' },

  { id: 'q5-14', moduleId: 5, difficulty: 'moyen', question: 'Quel empire détruit le Royaume du Nord d\'Israël en 722 avant l\'ère commune, dispersant les dix tribus ?', options: ['L\'Empire babylonien', 'L\'Empire perse', 'L\'Empire assyrien', 'L\'Empire égyptien'], correctAnswer: 2, explanation: 'Sargon II d\'Assyrie conquiert Samarie en 722 avant l\'ère commune, mettant fin au Royaume du Nord. Les dix tribus sont déportées et assimilées, d\'où l\'expression des « dix tribus perdues d\'Israël ».', source: 'II Rois 17:1-23 ; Annales de Sargon II' },

  { id: 'q5-15', moduleId: 5, difficulty: 'moyen', question: 'Quel est le nom de la déclaration britannique de 1917 soutenant la création d\'un foyer national juif en Palestine ?', options: ['Déclaration Balfour', 'Mandatoire britannique', 'Accord Sykes-Picot', 'Résolution 181 de l\'ONU'], correctAnswer: 0, explanation: 'La Déclaration Balfour, lettre du ministre britannique Arthur James Balfour adressée à Lord Walter Rothschild le 2 novembre 1917, exprime le soutien britannique à « l\'établissement en Palestine d\'un foyer national pour le peuple juif ».', source: 'Déclaration Balfour, 2 novembre 1917' },

  { id: 'q5-16', moduleId: 5, difficulty: 'difficile', question: 'Quel est le nom de la révolte juive contre Rome (132-135 de l\'ère commune) menée par Simon Bar Kokhba ?', options: ['Première Guerre judéo-romaine', 'Révolte de la Diaspora', 'Révolte de Bar Kokhba (Troisième Guerre judéo-romaine)', 'Révolte des Maccabées'], correctAnswer: 2, explanation: 'La révolte de Bar Kokhba (132-135 de l\'ère commune) est la troisième et dernière grande insurrection juive contre Rome. Son écrasement par Hadrien entraîne la fondation d\'Aelia Capitolina sur les ruines de Jérusalem et l\'interdiction aux Juifs d\'y habiter.', source: 'Talmud Bavli, Guittine 58a ; Dion Cassius, Histoire romaine LXIX, 12-14' },

  { id: 'q5-17', moduleId: 5, difficulty: 'difficile', question: 'Quelle résolution de l\'ONU de 1947 prévoit le partage de la Palestine en un État juif et un État arabe ?', options: ['Résolution 181', 'Résolution 242', 'Résolution 338', 'Résolution 194'], correctAnswer: 0, explanation: 'La Résolution 181 de l\'Assemblée générale des Nations Unies (29 novembre 1947) prévoit le partage de la Palestine mandataire en deux États. Le mouvement sioniste l\'accepte ; les États arabes la rejettent, déclenchant la guerre d\'Indépendance.', source: 'Résolution 181 de l\'Assemblée générale de l\'ONU, 29 novembre 1947' },

  { id: 'q5-18', moduleId: 5, difficulty: 'difficile', question: 'Quel est le terme désignant le retour en Israël au sens du droit (Loi du Retour de 1950) et son fondement biblique ?', options: ['Geoulah', 'Aliyah', 'Kiboutz Galuyot', 'Yeridah'], correctAnswer: 2, explanation: 'Le Kiboutz Galuyot (קִבּוּץ גָּלֻיּוֹת, « rassemblement des exilés ») est le concept prophétique du retour de toutes les communautés juives dispersées en terre d\'Israël. Il fonde théologiquement la Loi du Retour adoptée par la Knesset en 1950.', source: 'Isaïe 11:12 ; Ézéchiel 36:24 ; Loi du Retour (Israël, 1950)' },

  { id: 'q5-19', moduleId: 5, difficulty: 'difficile', question: 'Quel est le nom du dirigeant de la communauté juive de Palestine (Yichouv) qui proclame l\'indépendance d\'Israël le 14 mai 1948 ?', options: ['Hayim Weizmann', 'Menahem Begin', 'David Ben Gourion', 'Moshé Sharett'], correctAnswer: 2, explanation: 'David Ben Gourion (1886-1973), chef de l\'Agence juive et leader du Yichouv, proclame la naissance de l\'État d\'Israël le 14 mai 1948 à Tel-Aviv. Il devient le premier Premier ministre de l\'État hébreu.', source: 'Déclaration d\'indépendance d\'Israël, 14 mai 1948' },

  { id: 'q5-20', moduleId: 5, difficulty: 'difficile', question: 'Quel concept désigne le tribunal rabbinique suprême du Temple, composé de soixante-et-un membres, chargé de juger les grandes affaires religieuses ?', options: ['Beth Din', 'Knesset HaGuedolah', 'Sanhédrin HaGuadol', 'Moetset HaZkenim'], correctAnswer: 2, explanation: 'Le Grand Sanhédrin (סַנְהֶדְרִין גְּדוֹלָה) était le tribunal suprême de soixante-et-un membres siégeant dans la Lishkat HaGazit (salle des pierres taillées) du Temple. Il traitait les affaires capitales, religieuses et nationales.', source: 'Michna, Sanhédrin 1:1-6 ; Talmud Bavli, Sanhédrin 2a' },


  // ─── MODULE 6 : Les Prophètes ───────────────────────────────────────────────

  { id: 'q6-1', moduleId: 6, difficulty: 'facile', question: 'Quel prophète est connu pour sa vision du "char divin" (Merkava) ?', options: ['Isaïe', 'Jérémie', 'Ézéchiel', 'Amos'], correctAnswer: 2, explanation: 'Ézéchiel décrit au chapitre 1 une vision mystique du trône de Dieu porté par quatre créatures ailées, fondatrice de la mystique Merkava.', source: 'Ézéchiel 1:4-28' },

  { id: 'q6-2', moduleId: 6, difficulty: 'facile', question: 'Quel prophète fut envoyé à Ninive pour prêcher la repentance ?', options: ['Élie', 'Jonas', 'Amos', 'Jérémie'], correctAnswer: 1, explanation: 'Jonas reçut l\'ordre divin d\'aller à Ninive ; après sa fuite et son séjour dans le ventre d\'un grand poisson, il accomplit sa mission.', source: 'Jonas 1:1-2 ; 3:1-4' },

  { id: 'q6-3', moduleId: 6, difficulty: 'facile', question: 'Sur quel mont Élie affronta-t-il les prophètes de Baal ?', options: ['Mont Sinaï', 'Mont Hermon', 'Mont Carmel', 'Mont Tabor'], correctAnswer: 2, explanation: 'Au Mont Carmel, Élie défia 450 prophètes de Baal : seul l\'autel du Seigneur s\'enflamma, prouvant la toute-puissance de Dieu.', source: '1 Rois 18:19-39' },

  { id: 'q6-4', moduleId: 6, difficulty: 'facile', question: 'Quel prophète annonça la destruction du Premier Temple de Jérusalem ?', options: ['Isaïe', 'Jérémie', 'Ézéchiel', 'Michée'], correctAnswer: 1, explanation: 'Jérémie prophétisa la chute de Jérusalem et la captivité babylonienne, et fut témoin de la destruction du Temple en 586 av. J.-C.', source: 'Jérémie 7:1-15 ; 52:12-14' },

  { id: 'q6-5', moduleId: 6, difficulty: 'facile', question: 'Quel prophète est principalement associé à la défense de la justice sociale envers les pauvres ?', options: ['Jonas', 'Aggée', 'Amos', 'Zacharie'], correctAnswer: 2, explanation: 'Amos, berger devenu prophète au VIIIᵉ siècle av. J.-C., dénonça violemment l\'exploitation des pauvres et l\'injustice des élites d\'Israël.', source: 'Amos 5:24' },

  { id: 'q6-6', moduleId: 6, difficulty: 'facile', question: 'Quelle expression du livre d\'Isaïe désigne un personnage mystérieux qui souffre pour les fautes du peuple ?', options: ['Fils de l\'Homme', 'Serviteur souffrant', 'Messie d\'Aaron', 'Prince de la paix'], correctAnswer: 1, explanation: 'Les "Chants du Serviteur" (Isaïe 52-53) décrivent un serviteur souffrant dont la souffrance expie les fautes collectives ; ce texte est central dans la théologie juive et chrétienne.', source: 'Isaïe 52:13-53:12' },

  { id: 'q6-7', moduleId: 6, difficulty: 'facile', question: 'À quelle nation les habitants de Ninive appartenaient-ils selon le livre de Jonas ?', options: ['Babylon', 'Assyrie', 'Égypte', 'Perse'], correctAnswer: 1, explanation: 'Ninive était la capitale de l\'empire assyrien, ennemi d\'Israël ; c\'est pourquoi Jonas rechignait à prêcher en sa faveur.', source: 'Jonas 1:2 ; 2 Rois 19:36' },

  { id: 'q6-8', moduleId: 6, difficulty: 'moyen', question: 'Qu\'appelle-t-on la théorie du "Trito-Isaïe" ?', options: ['Isaïe est un seul auteur', 'Le livre d\'Isaïe aurait trois auteurs différents (ch. 1-39, 40-55, 56-66)', 'Isaïe est un double du livre de Jérémie', 'Les trois derniers chapitres d\'Isaïe sont apocryphes'], correctAnswer: 1, explanation: 'Les critiques bibliques distinguent Isaïe 1-39 (VIIIᵉ s.), Deutéro-Isaïe 40-55 (exil babylonien) et Trito-Isaïe 56-66 (post-exil), trois contextes historiques différents.', source: 'Isaïe 40:1 ; 56:1 — exégèse académique moderne' },

  { id: 'q6-9', moduleId: 6, difficulty: 'moyen', question: 'Quelle expression d\'Amos résume le mieux son message éthique ?', options: ['"Que le droit coule comme l\'eau"', '"Aimez le Seigneur votre Dieu"', '"Le Seigneur est mon berger"', '"Tu ne tueras pas"'], correctAnswer: 0, explanation: 'Amos 5:24 — "Que le droit coule comme l\'eau et la justice comme un torrent intarissable" — est devenu le cri de ralliement de toute éthique sociale juive.', source: 'Amos 5:24' },

  { id: 'q6-10', moduleId: 6, difficulty: 'moyen', question: 'Quel événement déclencheur conduit Jérémie à rédiger le Livre des Lamentations ?', options: ['La famine de Samarie', 'La destruction du Premier Temple', 'La mort du roi Josias', 'L\'exil du roi Jéhoïakim'], correctAnswer: 1, explanation: 'Les Lamentations (Eikha) sont traditionnellement attribuées à Jérémie et décrivent le deuil de Jérusalem après la destruction du Temple par Nabuchodonosor en 586 av. J.-C.', source: 'Lamentations 1:1 ; Talmud Bavli, Bava Batra 15a' },

  { id: 'q6-11', moduleId: 6, difficulty: 'moyen', question: 'Que signifie littéralement "Merkava" dans la vision d\'Ézéchiel ?', options: ['Trône', 'Char', 'Nuage', 'Gloire'], correctAnswer: 1, explanation: 'Merkava (מֶרְכָּבָה) signifie "char" en hébreu ; la vision d\'Ézéchiel au chapitre 1 décrit le trône de Dieu comme un char céleste tiré par des créatures à quatre faces.', source: 'Ézéchiel 1:4-28' },

  { id: 'q6-12', moduleId: 6, difficulty: 'moyen', question: 'Quelle image prophétique Ézéchiel utilise-t-il pour annoncer la renaissance d\'Israël après l\'exil ?', options: ['La vallée de sel', 'Les ossements desséchés', 'Le figuier stérile', 'Le buisson ardent'], correctAnswer: 1, explanation: 'Ézéchiel 37 décrit la vision d\'une vallée d\'ossements desséchés qui reprennent vie, symbole de la résurrection nationale d\'Israël après la catastrophe de 586 av. J.-C.', source: 'Ézéchiel 37:1-14' },

  { id: 'q6-13', moduleId: 6, difficulty: 'moyen', question: 'Combien de prophètes de Baal Élie affronta-t-il au Mont Carmel selon le texte biblique ?', options: ['100', '250', '450', '700'], correctAnswer: 2, explanation: 'Selon 1 Rois 18:19, Élie défia 450 prophètes de Baal et 400 prophètes d\'Achéra, seul contre tous, et remporta l\'épreuve du feu.', source: '1 Rois 18:19' },

  { id: 'q6-14', moduleId: 6, difficulty: 'moyen', question: 'Quel prophète fut surnommé "le pleureur" (ha-bakkhan) en raison de la tonalité de son œuvre ?', options: ['Ézéchiel', 'Amos', 'Jérémie', 'Isaïe'], correctAnswer: 2, explanation: 'Jérémie est traditionnellement appelé "le prophète pleureur" en raison des nombreuses plaintes et lamentations qui parsèment son livre, exprimant son désespoir devant la résistance du peuple.', source: 'Jérémie 9:1 ; Talmud Bavli, Bava Batra 15a' },

  { id: 'q6-15', moduleId: 6, difficulty: 'moyen', question: 'Quelle thématique centrale distingue le message d\'Isaïe (ch. 40-55) pendant l\'exil babylonien ?', options: ['Le châtiment divin', 'La consolation et le retour', 'L\'apocalypse imminente', 'La réforme du culte'], correctAnswer: 1, explanation: 'Le Deutéro-Isaïe (ch. 40-55) s\'ouvre sur "Consolez, consolez mon peuple" (40:1) et annonce le retour d\'exil comme une nouvelle sortie d\'Égypte, porteur d\'espoir.', source: 'Isaïe 40:1-11' },

  { id: 'q6-16', moduleId: 6, difficulty: 'difficile', question: 'Dans la mystique juive, quelle section du livre d\'Ézéchiel est considérée comme si ésotérique qu\'on déconseillait sa lecture publique ?', options: ['Le chapitre sur Gog et Magog', 'La vision de la Merkava (ch. 1)', 'La prophétie du Temple futur (ch. 40-48)', 'La résurrection des ossements (ch. 37)'], correctAnswer: 1, explanation: 'Le Talmud (Hagiga 13a) rapporte que la vision de la Merkava ne devait être enseignée qu\'en privé, à un seul disciple à la fois, tant le texte était jugé dangereux pour qui n\'était pas suffisamment préparé.', source: 'Talmud Bavli, Hagiga 13a ; Ézéchiel 1' },

  { id: 'q6-17', moduleId: 6, difficulty: 'difficile', question: 'Quelle notion théologique le prophète Jérémie introduit-il de façon novatrice concernant la relation individuelle avec Dieu ?', options: ['L\'élection nationale exclusive', 'La responsabilité collective uniquement', 'La nouvelle alliance inscrite dans le cœur', 'La punition des pères sur les fils'], correctAnswer: 2, explanation: 'Jérémie 31:31-34 annonce une "nouvelle alliance" (brit hadasha) non gravée sur des tables de pierre mais inscrite dans le cœur de chaque individu, marquant un tournant vers la responsabilité personnelle.', source: 'Jérémie 31:31-34' },

  { id: 'q6-18', moduleId: 6, difficulty: 'difficile', question: 'Quel terme hébreu désigne les quatre créatures à quatre faces qui portent le trône divin dans la vision d\'Ézéchiel ?', options: ['Séraphins', 'Kéruvim', 'Hayyot', 'Ofanim'], correctAnswer: 2, explanation: 'Les Hayyot (חַיּוֹת, "créatures vivantes") ont chacune quatre faces (homme, lion, bœuf, aigle) et quatre ailes ; elles sont distinctes des Ofanim (roues) et des Kéruvim.', source: 'Ézéchiel 1:5-14' },

  { id: 'q6-19', moduleId: 6, difficulty: 'difficile', question: 'Quel verset d\'Amos est cité par Martin Luther King dans son discours "I Have a Dream" comme appel à la justice ?', options: ['Amos 3:7', 'Amos 5:24', 'Amos 7:14', 'Amos 9:11'], correctAnswer: 1, explanation: 'Martin Luther King cite directement Amos 5:24 — "Que le droit coule comme l\'eau et la justice comme un torrent intarissable" — illustrant l\'universalité du message prophétique juif.', source: 'Amos 5:24' },

  { id: 'q6-20', moduleId: 6, difficulty: 'difficile', question: 'Dans quel livre prophétique trouve-t-on la formule "Pour trois crimes, pour quatre, je ne révoquerai pas le décret" répétée comme structure littéraire ?', options: ['Isaïe', 'Jérémie', 'Amos', 'Ézéchiel'], correctAnswer: 2, explanation: 'Amos utilise la formule numérique "pour trois, pour quatre" (Amos 1-2) comme procédé rhétorique pour annoncer le jugement sur les nations voisines puis sur Israël lui-même.', source: 'Amos 1:3, 6, 9, 11, 13 ; 2:1, 4, 6' },

  // ─── MODULE 7 : Grandes Figures du Judaïsme ─────────────────────────────────

  { id: 'q7-1', moduleId: 7, difficulty: 'facile', question: 'Quel philosophe juif médiéval a rédigé le "Guide des Égarés" (Moreh Nevoukhim) ?', options: ['Rachi', 'Maïmonide', 'Baal Shem Tov', 'Nachmanide'], correctAnswer: 1, explanation: 'Maïmonide (Rambam, 1138-1204) écrivit le Moreh Nevoukhim en judéo-arabe pour réconcilier la foi juive avec la philosophie aristotélicienne.', source: 'Maïmonide, Guide des Égarés, Introduction' },

  { id: 'q7-2', moduleId: 7, difficulty: 'facile', question: 'Combien d\'articles de foi Maïmonide a-t-il formulés dans ses 13 Principes ?', options: ['7', '10', '13', '18'], correctAnswer: 2, explanation: 'Les 13 Principes de Foi (Shloshah Asar Ikkarim) de Maïmonide sont récités dans la prière Yigdal et constituent la confession de foi la plus connue du judaïsme.', source: 'Maïmonide, Commentaire de la Michna, Introduction au ch. Heleq' },

  { id: 'q7-3', moduleId: 7, difficulty: 'facile', question: 'Rachi est principalement connu pour ses commentaires sur quels deux textes majeurs ?', options: ['La Torah et le Talmud', 'Le Talmud et le Zohar', 'La Torah et le Zohar', 'La Michna et la Guemara'], correctAnswer: 0, explanation: 'Rachi (Rabbi Chlomo Itzhaki, 1040-1105) rédigea des commentaires exhaustifs sur la Torah et le Talmud babylonien, encore incontournables dans l\'étude traditionnelle.', source: 'Rachi, Commentaire sur la Genèse 1:1 ; Rachi sur Talmud Bavli' },

  { id: 'q7-4', moduleId: 7, difficulty: 'facile', question: 'Qui est considéré comme le fondateur du mouvement hassidique ?', options: ['Rabbi Akiva', 'Maïmonide', 'Baal Shem Tov', 'Rachi'], correctAnswer: 2, explanation: 'Israel ben Eliezer (1698-1760), dit le Baal Shem Tov ("Maître du Bon Nom"), fonda le hassidisme en Ukraine, insistant sur la joie, la ferveur et l\'accès de tous à Dieu.', source: 'Martin Buber, Les Récits des Hassidim ; tradition hassidique' },

  { id: 'q7-5', moduleId: 7, difficulty: 'facile', question: 'Qu\'est-ce que la "Michné Torah" de Maïmonide ?', options: ['Un commentaire talmudique', 'Une codification systématique de toute la Halakha', 'Un traité de philosophie', 'Un recueil de poésies liturgiques'], correctAnswer: 1, explanation: 'La Michné Torah (XIV livres) est le premier code juridique complet de la loi juive, rédigé en hébreu clair pour que tout Juif puisse connaître les lois sans consulter le Talmud.', source: 'Maïmonide, Michné Torah, Introduction' },

  { id: 'q7-6', moduleId: 7, difficulty: 'facile', question: 'Abraham Joshua Heschel a décrit le Shabbat comme quoi dans son œuvre éponyme ?', options: ['Un Temple dans le temps', 'Un jardin dans l\'espace', 'Un palais royal', 'Une forteresse de l\'âme'], correctAnswer: 0, explanation: 'Dans "Le Shabbat" (1951), Heschel écrit que le Shabbat est "un palais dans le temps" ou "un sanctuaire temporel", renversant la priorité de l\'espace au profit du temps sacré.', source: 'Abraham Joshua Heschel, The Sabbath, 1951' },

  { id: 'q7-7', moduleId: 7, difficulty: 'moyen', question: 'Quel est le premier des 13 Principes de Maïmonide ?', options: ['La Torah est divine', 'L\'existence de Dieu', 'La résurrection des morts', 'La venue du Messie'], correctAnswer: 1, explanation: 'Le premier principe affirme l\'existence du Créateur — un Être parfait, premier cause de toutes choses — fondement de toute la foi juive selon Maïmonide.', source: 'Maïmonide, Commentaire de la Michna, Sanhédrin ch. Heleq' },

  { id: 'q7-8', moduleId: 7, difficulty: 'moyen', question: 'Dans quelle ville Rachi vécut-il et dirigea-t-il une académie talmudique renommée ?', options: ['Cordoue', 'Troyes', 'Tolède', 'Worms'], correctAnswer: 1, explanation: 'Rachi vécut toute sa vie à Troyes (Champagne, France) où il dirigea une yeshiva et écrivit ses commentaires décisifs sur fond de croisades et de persécutions.', source: 'Biographie de Rachi, Troyes, XIe siècle' },

  { id: 'q7-9', moduleId: 7, difficulty: 'moyen', question: 'Quelle notion centrale Emmanuel Levinas place-t-il au cœur de son éthique ?', options: ['L\'être-pour-soi', 'La responsabilité envers l\'Autre', 'Le contrat social', 'La volonté de puissance'], correctAnswer: 1, explanation: 'Levinas (1906-1995) fonde son éthique sur le "visage de l\'Autre" qui m\'interpelle et crée une responsabilité infinie avant tout choix libre — éthique nourrie de la tradition juive.', source: 'Emmanuel Levinas, Totalité et Infini, 1961' },

  { id: 'q7-10', moduleId: 7, difficulty: 'moyen', question: 'Quel surnom porte le Baal Shem Tov, et que signifie-t-il ?', options: ['Maître du Bon Nom', 'Lumière d\'Israël', 'Gardien de la Torah', 'Père des pauvres'], correctAnswer: 0, explanation: 'Baal Shem Tov (בַּעַל שֵׁם טוֹב) signifie "Maître du Bon Nom" en hébreu, désignant quelqu\'un capable d\'invoquer le Nom divin pour guérir et accomplir des prodiges.', source: 'Tradition hassidique ; Shivhei HaBesht' },

  { id: 'q7-11', moduleId: 7, difficulty: 'moyen', question: 'Quel 13e principe de Maïmonide porte spécifiquement sur la résurrection des morts ?', options: ['Le 11e principe', 'Le 12e principe', 'Le 13e principe', 'Le 7e principe'], correctAnswer: 2, explanation: 'Le 13e et dernier principe de Maïmonide affirme la techouva et la résurrection des morts (tehiyat ha-metim) comme vérité fondamentale de la foi juive.', source: 'Maïmonide, 13 Principes de Foi ; Yigdal' },

  { id: 'q7-12', moduleId: 7, difficulty: 'moyen', question: 'Quelle figure du XVIe siècle rédigea le Choulhan Aroukh, code de loi juive encore en vigueur aujourd\'hui ?', options: ['Rabbi Akiva', 'Maïmonide', 'Joseph Caro', 'Rachi'], correctAnswer: 2, explanation: 'Joseph Caro (1488-1575) rédigea à Safed le Choulhan Aroukh ("Table dressée"), synthèse halakhique adoptée comme autorité principale par les communautés juives séfarades et, avec les Mappot d\'Isserles, ashkénazes.', source: 'Joseph Caro, Choulhan Aroukh, 1565' },

  { id: 'q7-13', moduleId: 7, difficulty: 'moyen', question: 'Heschel affirme que le Shabbat est une "architecture du temps". Quelle en est l\'implication principale ?', options: ['L\'espace sacré prime sur le temps', 'Le temps peut être sanctifié autant que l\'espace', 'Le travail est une nécessité spirituelle', 'Les synagogues sont inutiles'], correctAnswer: 1, explanation: 'Heschel renverse la priorité civilisationnelle accordée à l\'espace (temples, nations) : pour lui, le Shabbat prouve que le temps peut être sanctuaire et que la sainteté habite le temps.', source: 'Abraham Joshua Heschel, The Sabbath, 1951' },

  { id: 'q7-14', moduleId: 7, difficulty: 'difficile', question: 'Quel concept philosophique Maïmonide emprunte-t-il à Aristote pour parler de Dieu dans le Guide des Égarés ?', options: ['L\'éternité du monde', 'La théologie négative (attributs négatifs)', 'L\'âme végétative', 'La catharsis'], correctAnswer: 1, explanation: 'Maïmonide adopte la "théologie négative" : on ne peut décrire Dieu que par ce qu\'Il n\'est pas (non-corporel, non-temporel…), car tout attribut positif limiterait Son infini.', source: 'Maïmonide, Guide des Égarés I, ch. 58' },

  { id: 'q7-15', moduleId: 7, difficulty: 'difficile', question: 'Levinas établit une distinction entre "le Dire" et "le Dit". Que désigne "le Dire" dans son éthique ?', options: ['Le contenu d\'une phrase', 'L\'acte même d\'adresse à l\'Autre, antérieur au contenu', 'La loi écrite de la Torah', 'La prière liturgique'], correctAnswer: 1, explanation: 'Pour Levinas, "le Dire" (le Dire éthique) est l\'exposition vulnérable à l\'Autre avant tout contenu ; "le Dit" en est la trace figée dans le langage — distinction centrale d\'Autrement qu\'être (1974).', source: 'Emmanuel Levinas, Autrement qu\'être ou au-delà de l\'essence, 1974' },

  { id: 'q7-16', moduleId: 7, difficulty: 'difficile', question: 'Quelle controverse entourait la diffusion des œuvres de Maïmonide dans certaines communautés médiévales ?', options: ['Ses positions sur la résurrection et l\'allégorisme menaçaient selon ses critiques la foi simple', 'Il refusait d\'étudier la Guemara', 'Il prônait le christianisme', 'Il interdisait les prières en hébreu'], correctAnswer: 0, explanation: 'La "controverse maïmonidéenne" (XIIIe s.) vit des rabbins brûler le Guide des Égarés : certains estimaient que sa philosophie grecque et son allégorisme fragilisaient la foi en la résurrection corporelle et les miracles.', source: 'Controverse maïmonidéenne, Montpellier / Barcelone, ~1232' },

  { id: 'q7-17', moduleId: 7, difficulty: 'difficile', question: 'Quel commentateur médiéval est appelé "Supercommentaire de Rachi" (Ba\'al HaTosafot en partie) et fut le petit-fils de Rachi ?', options: ['Nachmanide', 'Rashbam', 'Maïmonide', 'Joseph Caro'], correctAnswer: 1, explanation: 'Rashbam (Rabbi Samuel ben Méir, ~1080-1160), petit-fils de Rachi, développa son propre commentaire privilégiant le sens littéral (pshat) et corrigeant parfois l\'interprétation de son grand-père.', source: 'Rashbam, Commentaire sur la Genèse' },

  { id: 'q7-18', moduleId: 7, difficulty: 'difficile', question: 'Quel concept hassidique central, souvent attribué au Baal Shem Tov, signifie "attachement/communion avec Dieu" ?', options: ['Tikkoun', 'Deveikout', 'Kavanah', 'Hitbonenut'], correctAnswer: 1, explanation: 'La Deveikout (דְּבֵקוּת, "attachement") est l\'idéal hassidique d\'union constante à Dieu dans chaque acte quotidien, accessible à tous, pas seulement aux savants.', source: 'Baal Shem Tov, tradition hassidique ; Tsavaat HaRivash' },

  { id: 'q7-19', moduleId: 7, difficulty: 'moyen', question: 'En quelle langue Rachi rédigea-t-il principalement ses commentaires ?', options: ['Araméen', 'Judéo-arabe', 'Hébreu', 'Judéo-français'], correctAnswer: 2, explanation: 'Rachi écrivit en hébreu rabbinique, parsemé de gloses en vieux français (appelées "laaziym") pour expliquer des termes difficiles, précieux témoignage du français médiéval.', source: 'Rachi, Commentaire sur le Pentateuque, XIe siècle' },

  { id: 'q7-20', moduleId: 7, difficulty: 'moyen', question: 'Quel ouvrage de Heschel traite de la théologie prophétique comme "sympathie divine" ?', options: ['The Sabbath', 'Man Is Not Alone', 'The Prophets', 'God in Search of Man'], correctAnswer: 2, explanation: 'Dans "The Prophets" (1962), Heschel développe la notion de "pathos divin" : Dieu n\'est pas impassible mais est affecté par les actes humains, et les prophètes partagent cette émotion divine.', source: 'Abraham Joshua Heschel, The Prophets, 1962' },

  // ─── MODULE 8 : Éthique Juive ────────────────────────────────────────────────

  { id: 'q8-1', moduleId: 8, difficulty: 'facile', question: 'Que signifie littéralement "Tikkoun Olam" en hébreu ?', options: ['Prière du matin', 'Réparation du monde', 'Étude de la Torah', 'Charité envers les pauvres'], correctAnswer: 1, explanation: 'Tikkoun Olam (תִּקּוּן עוֹלָם) signifie littéralement "réparation" ou "correction du monde" ; le concept est devenu central dans l\'éthique sociale juive moderne.', source: 'Mishna, Guittine 4:2 ; Aleinou le-Chabeah' },

  { id: 'q8-2', moduleId: 8, difficulty: 'facile', question: 'Dans la tradition juive, la Tsedaka est-elle considérée comme optionnelle ou obligatoire ?', options: ['Optionnelle, acte de générosité volontaire', 'Obligatoire, acte de justice', 'Réservée aux riches', 'Limitée aux membres de la famille'], correctAnswer: 1, explanation: 'Tsedaka (צְדָקָה) vient de "tsedek" (justice) : donner n\'est pas un acte de générosité facultatif mais un devoir de justice ; même les pauvres doivent pratiquer la Tsedaka.', source: 'Talmud Bavli, Guittin 7b ; Maïmonide, Michné Torah, Lois des Dons aux Pauvres' },

  { id: 'q8-3', moduleId: 8, difficulty: 'facile', question: 'Que signifie "Pikouah Nefesh" dans la loi juive ?', options: ['Respect du Shabbat', 'Sauver une vie humaine prime sur presque toutes les mitsvot', 'Prière d\'urgence', 'Don aux pauvres en cas de famine'], correctAnswer: 1, explanation: 'Pikouah Nefesh (פִּקּוּחַ נֶפֶשׁ, "sauvetage d\'une vie") autorise, voire oblige, à violer presque toutes les lois — y compris le Shabbat — pour préserver une vie en danger.', source: 'Talmud Bavli, Yoma 85a-b ; Lévitique 18:5' },

  { id: 'q8-4', moduleId: 8, difficulty: 'facile', question: 'Quel terme hébreu désigne la médisance et le commérage préjudiciables dans l\'éthique juive ?', options: ['Lochon Hara', 'Kavod', 'Tsniout', 'Anavah'], correctAnswer: 0, explanation: 'Lochon Hara (לָשׁוֹן הָרָע, "mauvaise langue") désigne tout discours négatif sur autrui, même véridique ; Rabbi Israël Meir Kagan y consacra son ouvrage Hafets Haïm.', source: 'Lévitique 19:16 ; Hafets Haïm (Rabbi Israël Meir Kagan)' },

  { id: 'q8-5', moduleId: 8, difficulty: 'facile', question: 'Que signifie "Kavod HaBriot" ?', options: ['Honorer ses parents', 'Dignité de chaque être humain', 'Respect du Shabbat', 'Honneur rendu aux rabbins'], correctAnswer: 1, explanation: 'Kavod HaBriot (כְּבוֹד הַבְּרִיּוֹת, "dignité des créatures") est le principe halakhique selon lequel la dignité humaine peut suspendre certaines ordonnances rabbiniques.', source: 'Talmud Bavli, Berakhot 19b' },

  { id: 'q8-6', moduleId: 8, difficulty: 'facile', question: 'Quel rabbin du XIXe siècle fonda le mouvement Moussar destiné au perfectionnement moral individuel ?', options: ['Baal Shem Tov', 'Rabbi Israël Salanter', 'Hafets Haïm', 'Rambam'], correctAnswer: 1, explanation: 'Rabbi Israël Lipkin Salanter (1809-1883) créa le mouvement Moussar en Lituanie, insistant sur l\'introspection, l\'humilité et le travail assidu sur les traits de caractère.', source: 'Rabbi Israël Salanter, Or Israël' },

  { id: 'q8-7', moduleId: 8, difficulty: 'facile', question: 'Combien de niveaux de Tsedaka Maïmonide a-t-il définis dans sa célèbre hiérarchie ?', options: ['5', '7', '8', '10'], correctAnswer: 2, explanation: 'Maïmonide liste 8 degrés de Tsedaka, le plus élevé étant d\'aider quelqu\'un à devenir autonome (prêt, emploi, association), le plus bas donnant à contrecœur.', source: 'Maïmonide, Michné Torah, Lois des Dons aux Pauvres 10:7-14' },

  { id: 'q8-8', moduleId: 8, difficulty: 'moyen', question: 'Quel verset du Lévitique est souvent cité comme fondement biblique de l\'interdiction du Lochon Hara ?', options: ['Lévitique 19:2', 'Lévitique 19:16', 'Lévitique 18:5', 'Lévitique 25:10'], correctAnswer: 1, explanation: 'Lévitique 19:16 — "Tu n\'iras pas répandre des calomnies parmi ton peuple" — est le verset de référence pour l\'interdiction du Lochon Hara et de la médisance.', source: 'Lévitique 19:16 ; Hafets Haïm' },

  { id: 'q8-9', moduleId: 8, difficulty: 'moyen', question: 'Selon la halakha, Pikouah Nefesh suspend-il aussi l\'interdiction du Yom Kippour de manger ?', options: ['Non, Yom Kippour est absolu', 'Oui, sauver une vie prime même sur Yom Kippour', 'Seulement pour les non-juifs', 'Seulement avec accord rabbinique préalable'], correctAnswer: 1, explanation: 'Le principe Pikouah Nefesh s\'applique à Yom Kippour : un malade dont la vie est en danger doit manger et boire ; refuser de le nourrir serait interdit.', source: 'Talmud Bavli, Yoma 85a ; Choulhan Aroukh, Orah Haïm 618' },

  { id: 'q8-10', moduleId: 8, difficulty: 'moyen', question: 'Quel texte liturgique mentionne le Tikkoun Olam dans le contexte de la royauté divine universelle ?', options: ['Shema Israël', 'Kaddish', 'Aleinou le-Chabeah', 'Amida'], correctAnswer: 2, explanation: 'La prière Aleinou le-Chabeah conclut par l\'espoir de "rectifier le monde sous le règne du Tout-Puissant" (letakkèn olam be-malkout Shaddaï), donnant au Tikkoun Olam sa dimension eschatologique.', source: 'Aleinou le-Chabeah, deuxième paragraphe' },

  { id: 'q8-11', moduleId: 8, difficulty: 'moyen', question: 'Dans le mouvement Moussar, qu\'est-ce que le "Heshbon HaNefesh" (bilan de l\'âme) ?', options: ['Un recueil de prières', 'Un examen quotidien de conscience et de ses actes moraux', 'Un traité de droit rabbinique', 'Un chant de Shabbat'], correctAnswer: 1, explanation: 'Le Heshbon HaNefesh (חֶשְׁבּוֹן הַנֶּפֶשׁ, "compte de l\'âme") est une pratique moussar d\'inventaire moral quotidien popularisée par le rabbin Menahem Mendel Lefin au XIXe siècle.', source: 'Menahem Mendel Lefin, Heshbon HaNefesh, 1812' },

  { id: 'q8-12', moduleId: 8, difficulty: 'moyen', question: 'Quel concept éthique interdit dans la tradition juive de faire honte à quelqu\'un en public (littéralement "blanchir le visage") ?', options: ['Lochon Hara', 'Halvayat Panim', 'Ona\'at Devarim', 'Honat adam'], correctAnswer: 1, explanation: 'Halvayat Panim (הַלְבָּנַת פָּנִים, "blanchir le visage") désigne l\'acte de faire rougir quelqu\'un de honte en public ; le Talmud le compare à un meurtre car le sang quitte le visage.', source: 'Talmud Bavli, Bava Metsia 58b' },

  { id: 'q8-13', moduleId: 8, difficulty: 'moyen', question: 'Quel grand principe Rabbi Akiva cite-t-il comme "règle fondamentale de la Torah" ?', options: ['"Shema Israël"', '"Tu aimeras ton prochain comme toi-même"', '"Justice, justice tu poursuivras"', '"N\'ajoute rien à mes commandements"'], correctAnswer: 1, explanation: 'Rabbi Akiva déclare que "Tu aimeras ton prochain comme toi-même" (Lévitique 19:18) est le principe général (kelal gadol) de toute la Torah.', source: 'Talmud Yeroushalmi, Nedarim 9:4 ; Lévitique 19:18' },

  { id: 'q8-14', moduleId: 8, difficulty: 'moyen', question: 'Selon la loi juive, est-il permis de mentir pour préserver la paix (shalom) ?', options: ['Non, le mensonge est toujours interdit', 'Oui, dans certains cas pour préserver la paix entre personnes', 'Seulement pour les rabbins', 'Seulement en cas de vie en danger'], correctAnswer: 1, explanation: 'Le Talmud (Yevamot 65b) enseigne qu\'on peut modifier la vérité pour la paix (mipenei hashalom) : par exemple, Dieu lui-même "minimisa" les paroles de Sara pour éviter une dispute entre elle et Abraham.', source: 'Talmud Bavli, Yevamot 65b' },

  { id: 'q8-15', moduleId: 8, difficulty: 'difficile', question: 'Le concept de Tikkoun Olam trouve son origine kabbalistique chez quel mystique de Safed ?', options: ['Maïmonide', 'Rabbi Yitzhak Louria (le Ari)', 'Baal Shem Tov', 'Nachmanide'], correctAnswer: 1, explanation: 'Rabbi Yitzhak Louria (1534-1572), dit "le Ari", développa la cosmologie du Tsimtsoum et des "éclats divins" (nitsotsot) : le Tikkoun Olam désigne la restauration de ces éclats par les actes humains.', source: 'Louria, Ets Haïm ; Gershom Scholem, Major Trends in Jewish Mysticism' },

  { id: 'q8-16', moduleId: 8, difficulty: 'difficile', question: 'Quelle distinction halakhique fondamentale le droit juif opère-t-il entre "Bein Adam LaMakom" et "Bein Adam LeHavero" ?', options: ['Entre lois bibliques et rabbiniques', 'Entre devoirs envers Dieu et devoirs envers autrui', 'Entre lois positives et négatives', 'Entre lois de pureté et d\'impureté'], correctAnswer: 1, explanation: 'La halakha distingue les mitsvot "entre l\'homme et Dieu" (culte, Shabbat) des mitsvot "entre l\'homme et son prochain" (honnêteté, aide) ; le Yom Kippour expie les premières mais pas les secondes sans réconciliation préalable.', source: 'Michna, Yoma 8:9' },

  { id: 'q8-17', moduleId: 8, difficulty: 'difficile', question: 'Dans le mouvement Moussar, quel ouvrage médiéval de Rabbi Moshé Haïm Luzzato est considéré comme le texte central ?', options: ['Chovot HaLevavot', 'Messilat Yesharim', 'Sha\'aré Teshouva', 'Or Haïm'], correctAnswer: 1, explanation: 'Le Messilat Yesharim ("Sentier des Droits", 1740) de Ramhal (Luzzato) décrit les étapes ascendantes du développement moral jusqu\'à la sainteté ; il est au cœur des yeshivot Moussar.', source: 'Rabbi Moshé Haïm Luzzato, Messilat Yesharim, 1740' },

  { id: 'q8-18', moduleId: 8, difficulty: 'difficile', question: 'Quel principe halakhique permet de maintenir la dignité humaine même au détriment d\'une interdiction rabbinique, selon le Talmud ?', options: ['Pikouah Nefesh', 'Dina de-malkhouta dina', 'Kavod HaBriot', 'Eilu ve-eilu'], correctAnswer: 2, explanation: 'Le Talmud (Berakhot 19b) enseigne que "la dignité des créatures (Kavod HaBriot) est grande au point de repousser un interdit rabbinique" — principe essentiel pour adapter la halakha aux situations humaines.', source: 'Talmud Bavli, Berakhot 19b' },

  { id: 'q8-19', moduleId: 8, difficulty: 'moyen', question: 'Que signifie "Gam Zu LeTova" dans la tradition juive et quel sage est associé à cette expression ?', options: ['"Dieu est unique" — Rabbi Akiva', '"Ceci aussi est pour le bien" — Rabbi Nahum Ish Gamzo', '"Fais le bien" — Hillel', '"Sois humble" — Moïse'], correctAnswer: 1, explanation: 'Rabbi Nahum Ish Gamzo (dont le nom contient le mot "gam zo") répétait "Gam zu letova" ("ceci aussi est pour le bien") face à toutes les épreuves, illustrant la confiance absolue en la Providence.', source: 'Talmud Bavli, Ta\'anit 21a' },

  { id: 'q8-20', moduleId: 8, difficulty: 'difficile', question: 'Comment le mouvement Moussar définit-il les "midot" (traits de caractère) à travailler en priorité ?', options: ['Les 613 commandements de la Torah', 'Les vertus comme l\'humilité, la patience, la vérité, à développer par répétition et méthode', 'Les dix paroles du Sinaï', 'Les 13 principes de Maïmonide'], correctAnswer: 1, explanation: 'Le Moussar identifie des midot (מִדּוֹת, traits de caractère) — humilité (anavah), vérité (emet), patience (savlanut) — à cultiver par répétition consciente (chazzara) et étude intense de textes inspirants.', source: 'Rabbi Israël Salanter, Or Israël ; tradition Moussar' },

  // ─── MODULE 9 : Prière et Liturgie ───────────────────────────────────────────

  { id: 'q9-1', moduleId: 9, difficulty: 'facile', question: 'Combien de paragraphes compose le Shema Israël récité lors des offices ?', options: ['1', '2', '3', '4'], correctAnswer: 2, explanation: 'Le Shema comprend trois paragraphes : Deutéronome 6:4-9 (l\'amour de Dieu), Deutéronome 11:13-21 (récompense et punition) et Nombres 15:37-41 (les franges du tallith).', source: 'Deutéronome 6:4 ; Michna, Berakhot 2:1' },

  { id: 'q9-2', moduleId: 9, difficulty: 'facile', question: 'Quel est le premier verset du Shema Israël et que proclame-t-il ?', options: ['"Béni soit le Nom de Son règne glorieux"', '"Écoute Israël, l\'Éternel est notre Dieu, l\'Éternel est Un"', '"Tu aimeras l\'Éternel ton Dieu de tout ton cœur"', '"Souviens-toi du jour du Shabbat"'], correctAnswer: 1, explanation: 'Deutéronome 6:4 — "Shema Israël, Adonaï Elohenou, Adonaï Ehad" — proclame l\'unicité absolue de Dieu et constitue la confession de foi centrale du judaïsme.', source: 'Deutéronome 6:4' },

  { id: 'q9-3', moduleId: 9, difficulty: 'facile', question: 'Combien de bénédictions compte l\'Amida (Chmoné Esré) dans sa version quotidienne (jours de semaine) ?', options: ['7', '12', '18', '19'], correctAnswer: 3, explanation: 'L\'Amida des jours de semaine compte 19 bénédictions (initialement 18, une 19e contre les délateurs fut ajoutée) ; le nombre "18" reste dans le nom Chmoné Esré (dix-huit).', source: 'Talmud Bavli, Berakhot 28b ; Choulhan Aroukh, Orah Haïm 112' },

  { id: 'q9-4', moduleId: 9, difficulty: 'facile', question: 'Dans quel contexte le Kaddish est-il surtout connu dans la pratique juive contemporaine ?', options: ['Prière du matin uniquement', 'Prière de deuil récitée par les endeuillés', 'Bénédiction sur le pain de Shabbat', 'Prière de Yom Kippour'], correctAnswer: 1, explanation: 'Le Kaddish des endeuillés (Kaddish Yatom) est récité par les proches d\'un défunt pendant 11 mois, et paradoxalement ne mentionne pas la mort mais loue Dieu.', source: 'Siddour ; tradition halakhique, Yoré Déa 376' },

  { id: 'q9-5', moduleId: 9, difficulty: 'facile', question: 'Qu\'est-ce que la Havdalah ?', options: ['Prière d\'ouverture du Shabbat', 'Cérémonie séparant la fin du Shabbat du reste de la semaine', 'Bénédiction des enfants le vendredi soir', 'Lecture de la Torah le samedi matin'], correctAnswer: 1, explanation: 'La Havdalah (הַבְדָּלָה, "séparation") est célébrée à la fin du Shabbat (samedi soir) avec le vin, les épices et une bougie tressée, marquant le passage du sacré au profane.', source: 'Michna, Berakhot 5:2 ; Talmud Bavli, Pesahim 106a' },

  { id: 'q9-6', moduleId: 9, difficulty: 'facile', question: 'Qu\'est-ce que le Talith ?', options: ['Un livre de prières', 'Un châle de prière à franges (tsitsit)', 'Une boîte contenant des versets de la Torah', 'Un shofar'], correctAnswer: 1, explanation: 'Le Talith (טַלִּית) est un châle de prière dont les coins sont ornés de franges (tsitsit) conformément au commandement de Nombres 15:38-40, port obligatoire pendant les prières du matin.', source: 'Nombres 15:38-40 ; Choulhan Aroukh, Orah Haïm 8' },

  { id: 'q9-7', moduleId: 9, difficulty: 'facile', question: 'Quel est le nom de la grâce récitée après les repas incluant du pain ?', options: ['Kiddouch', 'Motsi', 'Birkat HaMazon', 'Havdalah'], correctAnswer: 2, explanation: 'La Birkat HaMazon (בִּרְכַּת הַמָּזוֹן, "bénédiction de la nourriture") est la grâce après les repas qui incluent du pain, composée de quatre bénédictions, bibliquement obligatoire selon Deutéronome 8:10.', source: 'Deutéronome 8:10 ; Talmud Bavli, Berakhot 48b' },

  { id: 'q9-8', moduleId: 9, difficulty: 'moyen', question: 'Quel verset de la Torah fonde l\'obligation biblique de réciter la Birkat HaMazon ?', options: ['Genèse 1:29', 'Deutéronome 8:10', 'Lévitique 19:18', 'Exode 20:8'], correctAnswer: 1, explanation: 'Deutéronome 8:10 — "Tu mangeras, tu seras rassasié et tu béniras l\'Éternel ton Dieu pour le bon pays qu\'Il t\'a donné" — est la base biblique de la bénédiction après le repas.', source: 'Deutéronome 8:10 ; Talmud Bavli, Berakhot 21a' },

  { id: 'q9-9', moduleId: 9, difficulty: 'moyen', question: 'Dans quelle langue le Kaddish est-il principalement récité ?', options: ['Hébreu', 'Araméen', 'Yiddish', 'Hébreu-araméen mélangé'], correctAnswer: 1, explanation: 'Le Kaddish est écrit presque entièrement en araméen, langue vernaculaire des communautés juives de Babylone, bien que sa version complète comporte quelques versets hébreux.', source: 'Siddour ; tradition liturgique, période talmudique' },

  { id: 'q9-10', moduleId: 9, difficulty: 'moyen', question: 'Que symbolisent les épices (besamim) dans la cérémonie de la Havdalah ?', options: ['La douceur de la Torah', 'La consolation et douceur laissées par la "âme supplémentaire" du Shabbat qui part', 'La fertilité de la terre d\'Israël', 'Le souvenir du Temple'], correctAnswer: 1, explanation: 'Selon la mystique juive, une "âme supplémentaire" (neshama yetéra) visite chaque Juif le Shabbat ; les épices de la Havdalah consolent l\'âme de son départ en lui laissant un parfum de sainteté.', source: 'Talmud Bavli, Beïtsa 16a ; Zohar, Teruma' },

  { id: 'q9-11', moduleId: 9, difficulty: 'moyen', question: 'Quel est l\'ordre des trois premiers mots du Kiddouch du vendredi soir commençant le Shabbat ?', options: ['"Barukh ata Adonaï"', '"Yom HaShishi"', '"Shema Israël"', '"Leshem Shabbat"'], correctAnswer: 1, explanation: 'Le Kiddouch du vendredi soir commence par "Yom HaShishi" (Genèse 1:31), reprenant la conclusion du sixième jour de la création avant de bénir le vin et de sanctifier le Shabbat.', source: 'Genèse 1:31-2:3 ; Choulhan Aroukh, Orah Haïm 271' },

  { id: 'q9-12', moduleId: 9, difficulty: 'moyen', question: 'Combien de fois par jour un homme juif observant récite-t-il l\'Amida ?', options: ['1', '2', '3', '4 (sauf Shabbat et fêtes)'], correctAnswer: 2, explanation: 'L\'Amida est récitée trois fois par jour : Shaharit (matin), Minha (après-midi) et Arvit (soir) ; une quatrième Amida (Moussaf) est ajoutée le Shabbat, les fêtes et Roch Hodech.', source: 'Talmud Bavli, Berakhot 26b ; Choulhan Aroukh, Orah Haïm 89' },

  { id: 'q9-13', moduleId: 9, difficulty: 'moyen', question: 'Quelles sont les deux matières des téfilines (phylactères) et que contiennent-elles ?', options: ['Pierre et métal, avec les Dix Commandements', 'Cuir et parchemin, avec quatre passages de la Torah', 'Tissu et cire, avec le Shema', 'Bois et cuir, avec une mezouza'], correctAnswer: 1, explanation: 'Les téfilines sont des boîtes en cuir noir contenant quatre passages de la Torah sur parchemin (Exode 13:1-10, 11-16 ; Deutéronome 6:4-9 ; 11:13-21), portées au bras et à la tête.', source: 'Exode 13:9 ; Deutéronome 6:8 ; Talmud Bavli, Menahot 34b' },

  { id: 'q9-14', moduleId: 9, difficulty: 'moyen', question: 'Que signifie "Chmoné Esré" et pourquoi ce nom est-il paradoxal aujourd\'hui ?', options: ['Dix-huit bénédictions, paradoxal car on en compte maintenant 19', 'Sept bénédictions, paradoxal car il y en a 10 le Shabbat', 'Vingt-quatre prières, paradoxal car il n\'y en a que 19', 'Douze prières, paradoxal car certaines sont doublées'], correctAnswer: 0, explanation: 'Chmoné Esré (שְׁמוֹנֶה עֶשְׂרֵה) signifie "dix-huit" en hébreu ; paradoxalement, la version actuelle compte 19 bénédictions depuis l\'ajout de la Birkat HaMinim (contre les dissidents) vers le Ier siècle de l\'ère commune.', source: 'Talmud Bavli, Berakhot 28b' },

  { id: 'q9-15', moduleId: 9, difficulty: 'difficile', question: 'Quelle est la signification théologique de réciter le Kaddish, qui ne mentionne pas la mort, lors du deuil ?', options: ['C\'est une erreur liturgique historique jamais corrigée', 'Sanctifier Dieu même dans la souffrance affirme la foi au-delà de la mort', 'Les endeuillés n\'ont pas le droit de mentionner Dieu', 'Le Kaddish remplace l\'interdit de parler du défunt'], correctAnswer: 1, explanation: 'Réciter des louanges de Dieu (Kiddouch HaShem) dans la douleur du deuil est un acte de foi profond : l\'endeuillé affirme que la grandeur divine transcende même la perte, sanctifiant Dieu devant la communauté.', source: 'Talmud Bavli, Berakhot 60b ; tradition du Kaddish Yatom' },

  { id: 'q9-16', moduleId: 9, difficulty: 'difficile', question: 'Quelle bénédiction de l\'Amida fut ajoutée sous Rabban Gamliel II à Yavneh et contre qui était-elle dirigée ?', options: ['Birkat HaTorah contre l\'ignorance', 'Birkat HaMinim contre les sectaires et judéo-chrétiens', 'Birkat Yehouda ve-Yeroushalaim contre Rome', 'Birkat HaGoyim contre les nations'], correctAnswer: 1, explanation: 'La Birkat HaMinim ("bénédiction contre les dissidents") fut rédigée vers 90 de l\'ère commune à Yavneh pour disqualifier les sectaires (minim), parfois interprétés comme visant aussi les judéo-chrétiens qui ne pouvaient la réciter.', source: 'Talmud Bavli, Berakhot 28b-29a' },

  { id: 'q9-17', moduleId: 9, difficulty: 'difficile', question: 'Dans la Birkat HaMazon, combien de bénédictions sont d\'origine biblique selon la tradition talmudique ?', options: ['Une seule (Hazan et Kol)', 'Les trois premières', 'Les deux premières uniquement', 'Toutes les quatre'], correctAnswer: 1, explanation: 'Le Talmud (Berakhot 48b) attribue la première bénédiction (Hazan) à Moïse, la deuxième (Haaretz) à Josué, la troisième (Boneh Yeroushalaim) à David et Salomon ; la quatrième fut ajoutée par les sages de Yavneh.', source: 'Talmud Bavli, Berakhot 48b' },

  { id: 'q9-18', moduleId: 9, difficulty: 'difficile', question: 'Quel philosophe médiéval considère la prière comme un acte d\'intellect qui doit être dirigé vers Dieu et non une demande de changement de la volonté divine ?', options: ['Rachi', 'Maïmonide', 'Baal Shem Tov', 'Nahmanide'], correctAnswer: 1, explanation: 'Maïmonide (Guide des Égarés III:51) décrit la vraie prière comme contemplation intellectuelle de Dieu (méditation sur Sa perfection), non comme tentative d\'infléchir Sa volonté immuable.', source: 'Maïmonide, Guide des Égarés III:51' },

  { id: 'q9-19', moduleId: 9, difficulty: 'moyen', question: 'Qu\'est-ce que la "Kavanah" dans le contexte de la prière juive ?', options: ['La mélodie de la prière', 'L\'intention, la concentration intérieure et la direction du cœur pendant la prière', 'Le livre de prières officiel', 'L\'heure précise de la prière'], correctAnswer: 1, explanation: 'La Kavanah (כַּוָּנָה, "intention") désigne la direction du cœur vers Dieu pendant la prière ; sans kavanah, la prière risque d\'être mécanique ; elle est particulièrement requise pour le premier verset du Shema.', source: 'Michna, Berakhot 2:1 ; Choulhan Aroukh, Orah Haïm 60:5' },

  { id: 'q9-20', moduleId: 9, difficulty: 'difficile', question: 'Quelle est la signification du nœud du tallith gadol et du nombre de fils de chaque coin selon la tradition ?', options: ['5 fils et 8 nœuds représentant les 13 attributs divins', '8 fils et 5 nœuds représentant "Adonaï Ehad" numériquement (13 + 39 = 613)', 'Le nombre de fils varie selon les coutumes mais les nœuds sont toujours au nombre de 7', 'Il n\'y a aucune signification symbolique reconnue'], correctAnswer: 1, explanation: 'Selon la tradition (Nombres Rabba 18:3), chaque coin a 8 fils et 5 nœuds ; 8+5=13 (valeur d\'Ehad, "Un") + 39 (valeur numérique d\'Adonaï selon gématrie) = 52 = 613 selon certains calculs — symbole de l\'unicité divine.', source: 'Nombres 15:38-40 ; Choulhan Aroukh, Orah Haïm 11' },

  // ─── MODULE 10 : Judaïsme Contemporain ──────────────────────────────────────

  { id: 'q10-1', moduleId: 10, difficulty: 'facile', question: 'Quel mouvement juif contemporain accepte l\'égalité totale des femmes dans le culte, y compris comme rabbines ?', options: ['Orthodoxe', 'Conservateur partiel', 'Réformé', 'Karaïte'], correctAnswer: 2, explanation: 'Le mouvement Réformé (né au XIXe siècle en Allemagne) a été le premier à ordonner des femmes rabbines (Regina Jonas, 1935 en Allemagne ; Sally Priesand, 1972 aux États-Unis).', source: 'UAHC (Union for Reform Judaism) ; ordination de Sally Priesand, 1972' },

  { id: 'q10-2', moduleId: 10, difficulty: 'facile', question: 'Qui est Eliezer Ben Yéhouda et quel est son rôle principal dans l\'histoire juive moderne ?', options: ['Fondateur du mouvement sioniste', 'Père de la renaissance de l\'hébreu comme langue vivante', 'Premier rabbin d\'Israël', 'Auteur de la Déclaration d\'Indépendance d\'Israël'], correctAnswer: 1, explanation: 'Eliezer Ben Yéhouda (1858-1922) s\'installa en Palestine et consacra sa vie à la renaissance de l\'hébreu comme langue quotidienne, créant des milliers de néologismes et publiant un dictionnaire monumental.', source: 'Eliezer Ben Yéhouda, Dictionnaire de la Langue Hébraïque, 1910-1940' },

  { id: 'q10-3', moduleId: 10, difficulty: 'facile', question: 'Quel auteur et survivant de la Shoah reçut le Prix Nobel de la Paix en 1986 pour son travail de mémoire et son combat contre l\'indifférence ?', options: ['Primo Levi', 'Elie Wiesel', 'Viktor Frankl', 'Simon Wiesenthal'], correctAnswer: 1, explanation: 'Elie Wiesel (1928-2016), auteur de La Nuit et de nombreuses œuvres sur la Shoah, reçut le Nobel de la Paix 1986 ; il devint la voix mondiale contre l\'indifférence et l\'oubli.', source: 'Elie Wiesel, La Nuit, 1958 ; Prix Nobel de la Paix, 1986' },

  { id: 'q10-4', moduleId: 10, difficulty: 'facile', question: 'Quelle date commémore la Déclaration d\'Indépendance de l\'État d\'Israël ?', options: ['14 mai 1947', '14 mai 1948', '29 novembre 1947', '5 juin 1967'], correctAnswer: 1, explanation: 'David Ben Gourion proclama l\'indépendance de l\'État d\'Israël le 14 mai 1948 (5 Iyar 5708), la veille de la fin du Mandat britannique sur la Palestine.', source: 'Déclaration d\'Indépendance d\'Israël, 14 mai 1948' },

  { id: 'q10-5', moduleId: 10, difficulty: 'facile', question: 'Qu\'est-ce que le mouvement Reconstructionniste fondé par Mordecaï Kaplan ?', options: ['Un courant orthodoxe modernisé', 'Un mouvement qui considère le judaïsme comme une civilisation en évolution', 'Un retour au judaïsme biblique uniquement', 'Un mouvement favorisant l\'assimilation totale'], correctAnswer: 1, explanation: 'Mordecaï Kaplan (1881-1983) fonda le Reconstructionnisme en affirmant que le judaïsme est une "civilisation religieuse en évolution" où la communauté, et non Dieu seul, est source de norme.', source: 'Mordecaï Kaplan, Judaism as a Civilization, 1934' },

  { id: 'q10-6', moduleId: 10, difficulty: 'facile', question: 'Quelle est la principale différence entre le judaïsme Conservateur et le judaïsme Réformé concernant la Halakha ?', options: ['Le Conservateur rejette complètement la Halakha', 'Le Conservateur maintient la Halakha mais l\'adapte par processus halakhique interne ; le Réformé la considère non contraignante', 'Le Réformé est plus strict sur la Halakha que le Conservateur', 'Les deux ont la même approche de la Halakha'], correctAnswer: 1, explanation: 'Le judaïsme Conservateur (Masorti) maintient l\'autorité de la Halakha tout en admettant son évolution par des décisions du Comité de Loi Juive ; le Réformé considère la Halakha comme guide non contraignant.', source: 'Solomon Schechter, Catholic Israel ; Union for Traditional Judaism' },

  { id: 'q10-7', moduleId: 10, difficulty: 'moyen', question: 'Quel théologien juif américain posa la question choc "Dieu est-il mort à Auschwitz ?" et quel nom porte sa position ?', options: ['Elie Wiesel — théologie du silence', 'Richard Rubenstein — théologie de la mort de Dieu', 'Emil Fackenheim — commandement de la mémoire', 'Hans Jonas — le Dieu souffrant'], correctAnswer: 1, explanation: 'Richard Rubenstein, dans After Auschwitz (1966), soutint que le Dieu de l\'Histoire ne peut être maintenu après Auschwitz et proposa une théologie "post-mortem" centrée sur la communauté et la nature.', source: 'Richard Rubenstein, After Auschwitz, 1966' },

  { id: 'q10-8', moduleId: 10, difficulty: 'moyen', question: 'Quel penseur formulé le "614e commandement" après la Shoah, affirmant que les Juifs n\'avaient pas le droit de donner à Hitler des victoires posthumes ?', options: ['Elie Wiesel', 'Richard Rubenstein', 'Emil Fackenheim', 'Yeshayahu Leibowitz'], correctAnswer: 2, explanation: 'Emil Fackenheim, dans The Jewish Return into History (1978), affirma qu\'un 614e commandement s\'impose : ne pas abandonner le judaïsme, car cela donnerait à Hitler une victoire posthume.', source: 'Emil Fackenheim, The Jewish Return into History, 1978' },

  { id: 'q10-9', moduleId: 10, difficulty: 'moyen', question: 'Quel mouvement féministe juif publia en 1972 le premier siddour (livre de prières) non sexiste avec un langage inclusif ?', options: ['Neshama Project', 'Havurah Movement', 'Ezrat Nashim', 'Rosh Hodesh Groups'], correctAnswer: 2, explanation: 'Le groupe Ezrat Nashim (fondé ~1971-72 dans le mouvement Conservateur américain) fut pionnier des revendications féministes juives : accès au minyan, ordination féminine, langage inclusif.', source: 'Ezrat Nashim, Statement of Purpose, 1972' },

  { id: 'q10-10', moduleId: 10, difficulty: 'moyen', question: 'Quel est le nom du premier Congrès Sioniste convoqué par Theodor Herzl et dans quelle ville eut-il lieu ?', options: ['Londres 1896', 'Bâle 1897', 'Vienne 1895', 'Budapest 1898'], correctAnswer: 1, explanation: 'Le Premier Congrès Sioniste se tint à Bâle en août 1897 et adopta le Programme de Bâle : "Créer pour le peuple juif un foyer en Palestine, garanti par le droit public."', source: 'Programme de Bâle, 1er Congrès Sioniste, 1897' },

  { id: 'q10-11', moduleId: 10, difficulty: 'moyen', question: 'Quelle est la position du judaïsme Orthodoxe sur l\'ordination des femmes rabbines ?', options: ['Acceptée depuis 2005', 'Refusée, le rabbinat restant exclusivement masculin', 'Acceptée uniquement pour les communautés séfarades', 'Acceptée sous le titre de "Maharat" sans le titre de rabbin'], correctAnswer: 1, explanation: 'Le judaïsme Orthodoxe traditionnel refuse l\'ordination féminine au rabbinat ; certaines institutions orthodoxes modernes accordent le titre de "Maharat" ou "Rabba" mais ce reste très controversé dans la communauté orthodoxe.', source: 'Rabbinical Council of America (RCA) ; tradition halakhique orthodoxe' },

  { id: 'q10-12', moduleId: 10, difficulty: 'moyen', question: 'Dans quel pays Eliezer Ben Yéhouda vécut-il et mena-t-il sa renaissance de la langue hébraïque ?', options: ['Russie', 'Palestine ottomane puis britannique', 'Allemagne', 'États-Unis'], correctAnswer: 1, explanation: 'Ben Yéhouda s\'installa à Jérusalem (alors sous domination ottomane) en 1881 et y passa le reste de sa vie, imposant l\'hébreu comme seule langue dans sa maison et ses interactions.', source: 'Eliezer Ben Yéhouda, biographie ; Jérusalem 1881-1922' },

  { id: 'q10-13', moduleId: 10, difficulty: 'moyen', question: 'Qu\'est-ce que la "Loi du Retour" (Hok HaShevout) en Israël, adoptée en 1950 ?', options: ['Loi obligeant les Juifs du monde à faire l\'aliya', 'Loi accordant à tout Juif le droit d\'immigrer en Israël et d\'y obtenir la citoyenneté', 'Loi sur le retour des propriétés confisquées', 'Loi sur le retour des archives juives d\'Europe'], correctAnswer: 1, explanation: 'La Loi du Retour (1950, amendée 1970) accorde à tout Juif, son conjoint, ses enfants et petits-enfants le droit d\'immigrer en Israël (aliya) et d\'y obtenir automatiquement la citoyenneté.', source: 'Loi du Retour, 5710-1950, État d\'Israël' },

  { id: 'q10-14', moduleId: 10, difficulty: 'moyen', question: 'Quel auteur juif américain, auteur de Beloved Stranger, contribua à populariser la spiritualité juive renouvelée dans les années 1970-80 ?', options: ['Elie Wiesel', 'Zalman Schachter-Shalomi', 'Joseph Telushkin', 'Arthur Waskow'], correctAnswer: 1, explanation: 'Zalman Schachter-Shalomi (1924-2014) fonda le mouvement Renewal (renouveau juif), fusionnant hassidisme, psychologie humaniste et spiritualité œcuménique pour revitaliser la pratique juive.', source: 'Zalman Schachter-Shalomi, Jewish Renewal movement, années 1960-80' },

  { id: 'q10-15', moduleId: 10, difficulty: 'difficile', question: 'Quel philosophe juif proposa le concept de "Dieu souffrant" (Gott leidet) après Auschwitz, abandonnant l\'omnipotence divine ?', options: ['Richard Rubenstein', 'Emil Fackenheim', 'Hans Jonas', 'Elie Wiesel'], correctAnswer: 2, explanation: 'Hans Jonas, dans Le Concept de Dieu après Auschwitz (1984), proposa un Dieu qui s\'est limité Lui-même en créant le monde (kénose), capable de souffrir mais non d\'intervenir, répondant ainsi au problème du mal.', source: 'Hans Jonas, Le Concept de Dieu après Auschwitz, 1984' },

  { id: 'q10-16', moduleId: 10, difficulty: 'difficile', question: 'Quel événement controversé de 1983 dans le judaïsme Conservateur américain marqua une rupture et la création du mouvement Massorti Union for Traditional Judaism ?', options: ['L\'adoption d\'une liturgie totalement en anglais', 'L\'ordination de femmes rabbines par le Jewish Theological Seminary', 'La suppression du Kaddish', 'L\'autorisation du mariage homosexuel'], correctAnswer: 1, explanation: 'En 1983, le Jewish Theological Seminary (JTS) décida d\'ordonner des femmes rabbines ; cela provoqua une scission et la création de l\'Union for Traditional Judaism (UTJ) par les opposants.', source: 'JTS, vote sur l\'ordination féminine, 1983' },

  { id: 'q10-17', moduleId: 10, difficulty: 'difficile', question: 'Quel penseur juif orthodoxe israélien soutint paradoxalement que l\'État d\'Israël n\'a aucune signification religieuse et doit être traité comme un simple État laïc ?', options: ['Rav Kook', 'Yeshayahu Leibowitz', 'Rabbi Soloveichik', 'Ovadia Yossef'], correctAnswer: 1, explanation: 'Yeshayahu Leibowitz (1903-1994), philosophe orthodoxe controversé, dénonçait la "religion politique" (kfiyat dat) et affirmait que l\'État d\'Israël n\'est qu\'une réalité politique sans signification messianique ou religieuse.', source: 'Yeshayahu Leibowitz, Judaism, Human Values and the Jewish State, 1992' },

  { id: 'q10-18', moduleId: 10, difficulty: 'difficile', question: 'Quel concept théologique Rav Kook développa-t-il pour intégrer le sionisme laïc dans une vision de la rédemption (Gueoulah) ?', options: ['La Halakha comme droit naturel universel', 'L\'athala de-Gueoulah — "commencement de la Rédemption" — dans lequel même les sionistes laïcs jouent un rôle divin inconscient', 'Le refus total de l\'État laïc', 'La séparation absolue du religieux et du politique'], correctAnswer: 1, explanation: 'Rav Abraham Isaac Kook (1865-1935), premier Grand Rabbin ashkénaze de Palestine, théorisa que les pionniers laïcs sionistes accomplissaient inconsciemment un rôle divin dans le processus de rédemption (athala de-Gueoulah).', source: 'Rav Kook, Orot HaTechiya ; Orot Israël' },

  { id: 'q10-19', moduleId: 10, difficulty: 'difficile', question: 'Quelle féministe juive académique publia en 1983 Standing Again at Sinai, refondant la théologie juive depuis une perspective féminine ?', options: ['Judith Plaskow', 'Rachel Adler', 'Blu Greenberg', 'Tamar Ross'], correctAnswer: 0, explanation: 'Judith Plaskow, dans Standing Again at Sinai (1990), affirme que les femmes doivent être reconnues comme partie prenante de la révélation au Sinaï, refondant la théologie juive sur une base inclusive et féministe.', source: 'Judith Plaskow, Standing Again at Sinai, 1990' },

  { id: 'q10-20', moduleId: 10, difficulty: 'difficile', question: 'Quel document officiel de l\'Union pour le Judaïsme Réformé (1976) affirma un retour aux pratiques traditionnelles comme observance volontaire plutôt que rejet systématique ?', options: ['Pittsburgh Platform (1885)', 'Columbus Platform (1937)', 'San Francisco Platform (Centenary Perspective, 1976)', 'Miami Platform (1997)'], correctAnswer: 2, explanation: 'La Centenary Perspective (San Francisco, 1976) marqua un virage : le Réformé américain reconnut la valeur des pratiques traditionnelles (Shabbat, hébreu, kashrout) comme choix volontaire d\'enrichissement spirituel, rompant avec le rejet systématique de Pittsburgh 1885.', source: 'CCAR Centenary Perspective, San Francisco, 1976' },
];
